#!/usr/bin/env python3
"""
Numeron Vuorovahti (V2) – 3 viikon työvuorolistan saldoseuranta (patch_period_balance.py):
1. PeriodBalanceManager.kt:
   - Tallentaa 3 viikon jakson päiväkohtaisen pohjasuunnitelman (filesDir/vv_period_baselines.json)
     automaattisesti VAIN vielä alkamattomille listoille (periodStart > tänään)
   - Lukitsee pohjan jakson alkaessa; tukee myös käsin päivittämistä / poistamista jaksoyhteenvedosta
   - Hyvittää sairauslomat (sick) ja muut poissaolot suunnitellun vuoropituuden mukaan (ei miinussaldoa)
   - Suojaa keskeneräistä kuluvaa päivää ennenaikaiselta miinukselta ennen vuoron päättymistä
2. NativeShiftsView.kt:
   - 3 viikon työvuorolistapalkki: vuorot • tunnit • aamu / ilta / yö + 2. rivi (Alkup. X h + värillinen Saldo)
   - Sairauslomapäivän hyvityssolu (suunnitellut kellonajat + "SL hyv.") ja päivädialogin tarkka erittely
   - Kuukausikoosteeseen värillinen saldo loppuun kun kuukaudella on seurattua jaksoa
   - Jaksoyhteenvetodialogiin julkaistu lista / hyväksiluettu / saldo + "Aseta nykyinen pohjaksi" / "Poista pohja"
3. NativeStampView.kt:
   - Etusivun Tänään-korttiin kompakti saldopalkki silloin kun aktiivisen jakson saldo poikkeaa suunnitellusta (!= 0)
4. SettingsDialogHelper.kt:
   - Asetuskytkin "Seuraa työvuorolistan tuntisaldoa" selkeällä tekstillä, että laskenta alkaa vasta
     seuraavasta vielä alkamattomasta listasta
5. MainActivity.kt & ShiftReminderReceiver.kt:
   - Tallentavat kuukausisynkan yhteydessä tulevien listojen pohjasuunnitelman (PeriodBalanceManager.recordMonthSnapshot)
6. app/build.gradle.kts: versionCode +1 ja versionName +1 (idempotentti)
"""

import re
import sys
from pathlib import Path

PERIOD_BALANCE_MANAGER_KT = 'package fi.numeron.vuorovahti\n\nimport android.content.Context\nimport org.json.JSONArray\nimport org.json.JSONObject\nimport java.io.File\nimport java.time.DayOfWeek\nimport java.time.LocalDate\nimport java.time.LocalDateTime\nimport java.time.LocalTime\nimport java.time.YearMonth\nimport java.time.format.DateTimeFormatter\nimport java.time.temporal.ChronoUnit\nimport kotlin.math.abs\n\ndata class PlannedDayBaseline(\n    val minutes: Int,\n    val startText: String,\n    val endText: String\n)\n\ndata class PeriodBaseline(\n    val periodStart: LocalDate,\n    val periodEnd: LocalDate,\n    val plannedDays: Map<LocalDate, PlannedDayBaseline>,\n    val capturedMonths: Set<String>,\n    val manualOverride: Boolean = false,\n    val updatedAtMs: Long = System.currentTimeMillis()\n) {\n    fun requiredMonths(): Set<String> {\n        val m1 = YearMonth.from(periodStart).toString()\n        val m2 = YearMonth.from(periodEnd).toString()\n        return if (m1 == m2) setOf(m1) else setOf(m1, m2)\n    }\n\n    fun isComplete(): Boolean {\n        return requiredMonths().all { it in capturedMonths } &&\n            plannedDays.values.any { it.minutes > 0 }\n    }\n\n    fun totalPlannedMinutes(): Int = plannedDays.values.sumOf { it.minutes }\n}\n\ndata class DayBalanceInfo(\n    val date: LocalDate,\n    val plannedMinutes: Int,\n    val plannedStartText: String,\n    val plannedEndText: String,\n    val actualMinutes: Int,\n    val effectiveMinutes: Int,\n    val diffMinutes: Int,\n    val isCreditedSick: Boolean,\n    val isCreditedOtherAbsence: Boolean\n)\n\ndata class PeriodBalanceResult(\n    val periodStart: LocalDate,\n    val periodEnd: LocalDate,\n    val baseline: PeriodBaseline,\n    val plannedMinutes: Int,\n    val effectiveMinutes: Int,\n    val diffMinutes: Int,\n    val creditedSickDays: Int,\n    val creditedSickMinutes: Int,\n    val dayDetails: Map<LocalDate, DayBalanceInfo>\n)\n\nobject PeriodBalanceManager {\n\n    const val PREF_ENABLED = "period_balance_tracking_enabled"\n    private const val FILE_NAME = "vv_period_baselines.json"\n    private const val PERIOD_DAYS = 21L\n\n    private val lock = Any()\n    private var loaded: Boolean = false\n    private val baselines = LinkedHashMap<LocalDate, PeriodBaseline>()\n\n    @Volatile\n    var version: Long = 0L\n        private set\n\n    fun isEnabled(context: Context): Boolean {\n        return context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n            .getBoolean(PREF_ENABLED, true)\n    }\n\n    fun resolveAnchorMonday(context: Context): LocalDate {\n        val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n        val raw = prefs.getString("shift_period_anchor_iso", "2026-12-28").orEmpty().trim()\n        val parsed = try {\n            LocalDate.parse(raw)\n        } catch (_: Exception) {\n            LocalDate.of(2026, 12, 28)\n        }\n        return parsed.with(DayOfWeek.MONDAY)\n    }\n\n    fun getPeriodBoundsForDate(context: Context, date: LocalDate): Pair<LocalDate, LocalDate> {\n        val anchor = resolveAnchorMonday(context)\n        val monday = date.with(DayOfWeek.MONDAY)\n        val daysFromAnchor = ChronoUnit.DAYS.between(anchor, monday)\n        val periodIdx = Math.floorDiv(daysFromAnchor, PERIOD_DAYS)\n        val start = anchor.plusDays(periodIdx * PERIOD_DAYS)\n        val end = start.plusDays(PERIOD_DAYS - 1L)\n        return start to end\n    }\n\n    private fun storageFile(context: Context): File = File(context.applicationContext.filesDir, FILE_NAME)\n\n    private fun ensureLoadedLocked(context: Context) {\n        if (loaded) return\n        loaded = true\n        try {\n            val file = storageFile(context)\n            if (!file.exists()) return\n            val root = JSONObject(file.readText(Charsets.UTF_8))\n            val arr = root.optJSONArray("periods") ?: return\n            baselines.clear()\n            for (i in 0 until arr.length()) {\n                val obj = arr.optJSONObject(i) ?: continue\n                val start = try {\n                    LocalDate.parse(obj.optString("periodStart", ""))\n                } catch (_: Exception) {\n                    continue\n                }\n                val end = try {\n                    LocalDate.parse(obj.optString("periodEnd", ""))\n                } catch (_: Exception) {\n                    start.plusDays(PERIOD_DAYS - 1L)\n                }\n                val months = mutableSetOf<String>()\n                val mArr = obj.optJSONArray("capturedMonths")\n                if (mArr != null) {\n                    for (j in 0 until mArr.length()) {\n                        val m = mArr.optString(j, "").trim()\n                        if (m.isNotEmpty()) months.add(m)\n                    }\n                }\n                val daysMap = LinkedHashMap<LocalDate, PlannedDayBaseline>()\n                val dArr = obj.optJSONArray("plannedDays")\n                if (dArr != null) {\n                    for (j in 0 until dArr.length()) {\n                        val dObj = dArr.optJSONObject(j) ?: continue\n                        val dDate = try {\n                            LocalDate.parse(dObj.optString("date", ""))\n                        } catch (_: Exception) {\n                            continue\n                        }\n                        val mins = dObj.optInt("minutes", 0)\n                        if (mins > 0) {\n                            daysMap[dDate] = PlannedDayBaseline(\n                                minutes = mins,\n                                startText = dObj.optString("startText", ""),\n                                endText = dObj.optString("endText", "")\n                            )\n                        }\n                    }\n                }\n                baselines[start] = PeriodBaseline(\n                    periodStart = start,\n                    periodEnd = end,\n                    plannedDays = daysMap,\n                    capturedMonths = months,\n                    manualOverride = obj.optBoolean("manualOverride", false),\n                    updatedAtMs = obj.optLong("updatedAtMs", 0L)\n                )\n            }\n        } catch (_: Exception) {\n        }\n    }\n\n    private fun persistLocked(context: Context) {\n        try {\n            // Siivotaan yli 180 pv sitten päättyneet vanhat pohjasuunnitelmat\n            val cutoff = LocalDate.now().minusDays(180)\n            val staleKeys = baselines.values.filter { it.periodEnd.isBefore(cutoff) }.map { it.periodStart }\n            for (k in staleKeys) baselines.remove(k)\n\n            val root = JSONObject()\n            val arr = JSONArray()\n            for (b in baselines.values.sortedBy { it.periodStart }) {\n                val obj = JSONObject().apply {\n                    put("periodStart", b.periodStart.toString())\n                    put("periodEnd", b.periodEnd.toString())\n                    put("manualOverride", b.manualOverride)\n                    put("updatedAtMs", b.updatedAtMs)\n                }\n                val mArr = JSONArray()\n                for (m in b.capturedMonths.sorted()) mArr.put(m)\n                obj.put("capturedMonths", mArr)\n\n                val dArr = JSONArray()\n                for ((date, entry) in b.plannedDays.entries.sortedBy { it.key }) {\n                    dArr.put(\n                        JSONObject().apply {\n                            put("date", date.toString())\n                            put("minutes", entry.minutes)\n                            put("startText", entry.startText)\n                            put("endText", entry.endText)\n                        }\n                    )\n                }\n                obj.put("plannedDays", dArr)\n                arr.put(obj)\n            }\n            root.put("periods", arr)\n            storageFile(context).writeText(root.toString(), Charsets.UTF_8)\n        } catch (_: Exception) {\n        }\n    }\n\n    fun getBaseline(context: Context, periodStart: LocalDate): PeriodBaseline? {\n        return synchronized(lock) {\n            ensureLoadedLocked(context)\n            baselines[periodStart]\n        }\n    }\n\n    private fun shiftDurationMinutes(shift: CalendarDisplayShift): Int {\n        return if (shift.endMinutes >= shift.startMinutes) {\n            shift.endMinutes - shift.startMinutes\n        } else {\n            (24 * 60 - shift.startMinutes) + shift.endMinutes\n        }\n    }\n\n    private fun summarizeDayShifts(shifts: List<CalendarDisplayShift>): PlannedDayBaseline? {\n        if (shifts.isEmpty()) return null\n        val total = shifts.sumOf { shiftDurationMinutes(it) }\n        if (total <= 0) return null\n        val first = shifts.minByOrNull { it.startMinutes } ?: shifts.first()\n        val last = shifts.maxByOrNull { it.startMinutes } ?: shifts.last()\n        return PlannedDayBaseline(\n            minutes = total,\n            startText = first.startText,\n            endText = last.endText\n        )\n    }\n\n    /**\n     * Tallentaa automaattisesti pohjasuunnitelman VAIN vielä alkamattomille 3 viikon jaksoille\n     * (periodStart > tänään). Kun jakso on alkanut, pohjaa ei enää muuteta automaattisesti.\n     */\n    fun recordMonthSnapshot(context: Context, monthData: MonthDisplayData) {\n        if (!isEnabled(context) || DemoModeHelper.isDemoEnabled(context)) return\n\n        val ym = try {\n            YearMonth.of(monthData.year, monthData.month)\n        } catch (_: Exception) {\n            return\n        }\n        val monthKey = ym.toString()\n        val firstOfMonth = ym.atDay(1)\n        val lastOfMonth = ym.atEndOfMonth()\n        val today = LocalDate.now()\n\n        // Etsitään kaikki 3 viikon jaksot, jotka osuvat tähän kuukauteen\n        val overlappingPeriods = LinkedHashSet<Pair<LocalDate, LocalDate>>()\n        var cursor = firstOfMonth\n        while (!cursor.isAfter(lastOfMonth)) {\n            overlappingPeriods.add(getPeriodBoundsForDate(context, cursor))\n            cursor = cursor.plusDays(7)\n        }\n        overlappingPeriods.add(getPeriodBoundsForDate(context, lastOfMonth))\n\n        synchronized(lock) {\n            ensureLoadedLocked(context)\n            var changed = false\n\n            for ((pStart, pEnd) in overlappingPeriods) {\n                // Tärkeä sääntö: laskenta ja automaattitallennus alkaa VASTA alkamattomista listoista\n                if (!pStart.isAfter(today)) continue\n\n                val existing = baselines[pStart]\n                if (existing != null && existing.manualOverride) continue\n\n                val rangeStart = if (pStart.isAfter(firstOfMonth)) pStart else firstOfMonth\n                val rangeEnd = if (pEnd.isBefore(lastOfMonth)) pEnd else lastOfMonth\n\n                val monthPlanned = LinkedHashMap<LocalDate, PlannedDayBaseline>()\n                var d = rangeStart\n                while (!d.isAfter(rangeEnd)) {\n                    val day = monthData.days[d]\n                    if (day != null && day.shifts.isNotEmpty()) {\n                        summarizeDayShifts(day.shifts)?.let { monthPlanned[d] = it }\n                    }\n                    d = d.plusDays(1)\n                }\n\n                // Kuukauden osuus tallennetaan jos jaksossa on vuoroja tässä kuukaudessa\n                // TAI jakson toinen kuukausi on jo julkaistu (jolloin tämä osa koostuu vapaapäivistä)\n                val otherMonthAlreadyCaptured = existing != null &&\n                    existing.plannedDays.isNotEmpty() &&\n                    existing.capturedMonths.any { it != monthKey }\n                if (monthPlanned.isEmpty() && !otherMonthAlreadyCaptured) continue\n\n                val mergedDays = LinkedHashMap<LocalDate, PlannedDayBaseline>()\n                existing?.plannedDays?.forEach { (date, entry) ->\n                    if (YearMonth.from(date) != ym) {\n                        mergedDays[date] = entry\n                    }\n                }\n                mergedDays.putAll(monthPlanned)\n\n                val mergedMonths = LinkedHashSet<String>()\n                existing?.capturedMonths?.let { mergedMonths.addAll(it) }\n                mergedMonths.add(monthKey)\n\n                if (existing == null || existing.plannedDays != mergedDays || existing.capturedMonths != mergedMonths) {\n                    baselines[pStart] = PeriodBaseline(\n                        periodStart = pStart,\n                        periodEnd = pEnd,\n                        plannedDays = mergedDays,\n                        capturedMonths = mergedMonths,\n                        manualOverride = false,\n                        updatedAtMs = System.currentTimeMillis()\n                    )\n                    changed = true\n                }\n            }\n\n            if (changed) {\n                version++\n                persistLocked(context)\n            }\n        }\n    }\n\n    fun saveManualBaseline(\n        context: Context,\n        periodStart: LocalDate,\n        periodEnd: LocalDate,\n        combinedDayMap: Map<LocalDate, CalendarDisplayDay>\n    ): Boolean {\n        val planned = LinkedHashMap<LocalDate, PlannedDayBaseline>()\n        var d = periodStart\n        while (!d.isAfter(periodEnd)) {\n            val day = combinedDayMap[d]\n            if (day != null && day.shifts.isNotEmpty()) {\n                summarizeDayShifts(day.shifts)?.let { planned[d] = it }\n            }\n            d = d.plusDays(1)\n        }\n        if (planned.isEmpty()) return false\n\n        val reqMonths = LinkedHashSet<String>().apply {\n            add(YearMonth.from(periodStart).toString())\n            add(YearMonth.from(periodEnd).toString())\n        }\n        synchronized(lock) {\n            ensureLoadedLocked(context)\n            baselines[periodStart] = PeriodBaseline(\n                periodStart = periodStart,\n                periodEnd = periodEnd,\n                plannedDays = planned,\n                capturedMonths = reqMonths,\n                manualOverride = true,\n                updatedAtMs = System.currentTimeMillis()\n            )\n            version++\n            persistLocked(context)\n        }\n        return true\n    }\n\n    fun removeBaseline(context: Context, periodStart: LocalDate) {\n        synchronized(lock) {\n            ensureLoadedLocked(context)\n            if (baselines.remove(periodStart) != null) {\n                version++\n                persistLocked(context)\n            }\n        }\n    }\n\n    fun computePeriodBalance(\n        context: Context,\n        periodStart: LocalDate,\n        periodEnd: LocalDate,\n        combinedDayMap: Map<LocalDate, CalendarDisplayDay>,\n        availableMonths: Set<String>\n    ): PeriodBalanceResult? {\n        if (!isEnabled(context) || DemoModeHelper.isDemoEnabled(context)) return null\n        val baseline = getBaseline(context, periodStart) ?: return null\n        if (!baseline.isComplete()) return null\n\n        val reqMonths = baseline.requiredMonths()\n        if (!reqMonths.all { it in availableMonths }) return null\n\n        val today = LocalDate.now()\n        val now = LocalDateTime.now()\n\n        var totalPlanned = 0\n        var totalEffective = 0\n        var creditedSickDays = 0\n        var creditedSickMinutes = 0\n        val dayDetails = LinkedHashMap<LocalDate, DayBalanceInfo>()\n\n        var d = periodStart\n        while (!d.isAfter(periodEnd)) {\n            val plannedEntry = baseline.plannedDays[d]\n            val plannedMin = plannedEntry?.minutes ?: 0\n            val currentDay = combinedDayMap[d]\n            val shifts = currentDay?.shifts.orEmpty()\n            val actualMin = shifts.sumOf { shiftDurationMinutes(it) }\n            val hasSick = currentDay?.absences?.any { it.kind == "sick" } == true\n            val hasOtherAbsence = currentDay?.absences?.any { it.kind != "sick" } == true\n\n            var effectiveMin: Int\n            var isCreditedSick = false\n            var isCreditedOther = false\n\n            if (hasSick && plannedMin > 0) {\n                effectiveMin = maxOf(actualMin, plannedMin)\n                if (actualMin < plannedMin) {\n                    isCreditedSick = true\n                    creditedSickDays++\n                    creditedSickMinutes += (plannedMin - actualMin)\n                }\n            } else if (hasOtherAbsence && plannedMin > 0 && actualMin < plannedMin) {\n                effectiveMin = plannedMin\n                isCreditedOther = true\n            } else if (d == today && plannedMin > 0 && actualMin < plannedMin) {\n                // Keskeneräisestä kuluvasta päivästä ei lasketa miinusta ennen vuoron päättymistä\n                val plannedEnd = parsePlannedEndDateTime(d, plannedEntry)\n                effectiveMin = if (plannedEnd == null || now.isBefore(plannedEnd)) plannedMin else actualMin\n            } else {\n                effectiveMin = actualMin\n            }\n\n            val diff = effectiveMin - plannedMin\n            totalPlanned += plannedMin\n            totalEffective += effectiveMin\n\n            if (plannedMin > 0 || actualMin > 0 || isCreditedSick || isCreditedOther) {\n                dayDetails[d] = DayBalanceInfo(\n                    date = d,\n                    plannedMinutes = plannedMin,\n                    plannedStartText = plannedEntry?.startText.orEmpty(),\n                    plannedEndText = plannedEntry?.endText.orEmpty(),\n                    actualMinutes = actualMin,\n                    effectiveMinutes = effectiveMin,\n                    diffMinutes = diff,\n                    isCreditedSick = isCreditedSick,\n                    isCreditedOtherAbsence = isCreditedOther\n                )\n            }\n            d = d.plusDays(1)\n        }\n\n        return PeriodBalanceResult(\n            periodStart = periodStart,\n            periodEnd = periodEnd,\n            baseline = baseline,\n            plannedMinutes = totalPlanned,\n            effectiveMinutes = totalEffective,\n            diffMinutes = totalEffective - totalPlanned,\n            creditedSickDays = creditedSickDays,\n            creditedSickMinutes = creditedSickMinutes,\n            dayDetails = dayDetails\n        )\n    }\n\n    /**\n     * Laskee parhaillaan meneillään olevan 3 viikon jakson saldon välimuistista (kutsu IO-säikeessä).\n     */\n    fun computeCurrentPeriodBalance(context: Context): PeriodBalanceResult? {\n        if (!isEnabled(context) || DemoModeHelper.isDemoEnabled(context)) return null\n        val today = LocalDate.now()\n        val (pStart, pEnd) = getPeriodBoundsForDate(context, today)\n        val baseline = getBaseline(context, pStart) ?: return null\n        if (!baseline.isComplete()) return null\n\n        val yms = linkedSetOf(YearMonth.from(pStart), YearMonth.from(pEnd))\n        val combined = LinkedHashMap<LocalDate, CalendarDisplayDay>()\n        val availableMonths = LinkedHashSet<String>()\n\n        for (ym in yms) {\n            val cached = NumeronApiClient.loadMonthDisplayCache(context, ym.year, ym.monthValue)\n            if (cached != null) {\n                availableMonths.add(ym.toString())\n                combined.putAll(cached.days)\n            }\n        }\n        return computePeriodBalance(context, pStart, pEnd, combined, availableMonths)\n    }\n\n    private fun parsePlannedEndDateTime(date: LocalDate, entry: PlannedDayBaseline?): LocalDateTime? {\n        if (entry == null || entry.endText.isBlank()) return null\n        val fmt = DateTimeFormatter.ofPattern("H:mm")\n        return try {\n            val sTime = if (entry.startText.isNotBlank()) LocalTime.parse(entry.startText.trim(), fmt) else null\n            val eTime = LocalTime.parse(entry.endText.trim(), fmt)\n            val endDate = if (sTime != null && eTime.isBefore(sTime)) date.plusDays(1) else date\n            LocalDateTime.of(endDate, eTime)\n        } catch (_: Exception) {\n            null\n        }\n    }\n\n    fun formatSignedHours(diffMinutes: Int, en: Boolean): String {\n        val sep = if (en) "." else ","\n        if (diffMinutes == 0) return "±0${sep}0 h"\n        val sign = if (diffMinutes > 0) "+" else "−"\n        val absMin = abs(diffMinutes)\n        if (absMin < 60 && absMin % 6 != 0) {\n            return if (en) "${sign}${absMin}m" else "${sign}${absMin} min"\n        }\n        val hoursStr = String.format("%.1f", absMin / 60.0).replace(".", sep)\n        return "$sign$hoursStr h"\n    }\n\n    fun formatSignedExact(diffMinutes: Int, en: Boolean): String {\n        if (diffMinutes == 0) return if (en) "±0m" else "±0 min"\n        val sign = if (diffMinutes > 0) "+" else "−"\n        val absMin = abs(diffMinutes)\n        val h = absMin / 60\n        val m = absMin % 60\n        return when {\n            h > 0 && m > 0 -> if (en) "${sign}${h}h ${m}m" else "${sign}${h} h ${m} min"\n            h > 0 -> if (en) "${sign}${h}h" else "${sign}${h} h"\n            else -> if (en) "${sign}${m}m" else "${sign}${m} min"\n        }\n    }\n\n    fun formatHoursDecimal(totalMinutes: Int, en: Boolean): String {\n        val sep = if (en) "." else ","\n        return String.format("%.1f", totalMinutes / 60.0).replace(".", sep)\n    }\n}\n'

NATIVE_STAMP_VIEW_KT = 'package fi.numeron.vuorovahti\n\nimport android.content.Context\nimport android.graphics.Color\nimport android.graphics.Typeface\nimport android.os.Handler\nimport android.os.Looper\nimport android.text.Editable\nimport android.text.InputFilter\nimport android.text.TextWatcher\nimport android.transition.AutoTransition\nimport android.transition.TransitionManager\nimport android.util.TypedValue\nimport android.view.Gravity\nimport android.view.HapticFeedbackConstants\nimport android.view.View\nimport android.widget.Button\nimport android.widget.EditText\nimport android.widget.FrameLayout\nimport android.widget.LinearLayout\nimport android.widget.ProgressBar\nimport android.widget.ScrollView\nimport android.widget.TextView\nimport android.widget.Toast\nimport androidx.appcompat.app.AlertDialog\nimport androidx.swiperefreshlayout.widget.SwipeRefreshLayout\nimport kotlinx.coroutines.CoroutineScope\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.Job\nimport kotlinx.coroutines.launch\nimport kotlinx.coroutines.withContext\nimport java.time.Duration\nimport java.time.LocalDate\nimport java.time.LocalDateTime\nimport java.time.LocalTime\nimport java.time.format.DateTimeFormatter\n\nclass NativeStampView(\n    private val context: Context,\n    private val scope: CoroutineScope,\n    private val onOpenForgottenStampWeb: () -> Unit,\n    private val onOpenEditStampWeb: (rowId: String) -> Unit,\n    private val onOpenSettings: () -> Unit\n) : LinearLayout(context) {\n\n    private var currentState: StampingPageState? = null\n    private var selectedReasonCodeId: Int = 0\n    private var isSubmitting: Boolean = false\n    private var isOptionsExpanded: Boolean = false\n    private var lastSuccessfulStampMs: Long = 0L\n    private var lastNetworkFetchMs: Long = 0L\n    private var lastSessionEpoch: Long = -1L\n    private var lastRenderedState: StampingPageState? = null\n    private var lastRenderedNextShift: String? = null\n    private var lastRenderedLangEn: Boolean? = null\n    private var lastRenderedDemo: Boolean? = null\n    private var lastRenderedAmoled: Boolean? = null\n    private var lastRenderedBalanceKey: String? = null\n    private var cachedNextShiftText: String? = null\n    private var cachedPeriodBalance: PeriodBalanceResult? = null\n    private var loadJob: Job? = null\n\n    private val tickerHandler = Handler(Looper.getMainLooper())\n    private val liveDurationRunnable = object : Runnable {\n        override fun run() {\n            updateWorkingStatusPill()\n            tickerHandler.postDelayed(this, 30_000L)\n        }\n    }\n\n    private val swipeRefresh: SwipeRefreshLayout\n    private val todayCard: LinearLayout\n    private val stampCard: LinearLayout\n    private val historyCard: LinearLayout\n\n    private val txtTodayCaption: TextView\n    private val btnRefresh: Button\n    private val progressBar: ProgressBar\n    private val txtStatus: TextView\n    private val txtWorkingPill: TextView\n    private val txtShiftTimes: TextView\n    private val txtShiftWorkplace: TextView\n    private val txtShiftDetails: TextView\n    private val shiftProgressContainer: LinearLayout\n    private val txtShiftRemaining: TextView\n    private val shiftProgressTrack: LinearLayout\n    private val shiftProgressFill: View\n    private val shiftProgressRest: View\n    private val txtPeriodBalance: TextView\n    private val txtNextShift: TextView\n\n    private val txtStampCaption: TextView\n    private val btnPunch: Button\n    private val btnOptionsToggle: Button\n    private val optionsContainer: LinearLayout\n    private val txtReasonLabel: TextView\n    private val btnReasonSelector: Button\n    private val txtCommentLabel: TextView\n    private val editComment: EditText\n    private val btnForgotten: Button\n\n    private val txtLatestCaption: TextView\n    private val stampsListContainer: LinearLayout\n    private val btnShowMore: Button\n\n    init {\n        orientation = VERTICAL\n\n        swipeRefresh = SwipeRefreshLayout(context).apply {\n            setOnRefreshListener { loadState(forceNetwork = true, fromSwipe = true) }\n        }\n\n        val scroll = ScrollView(context).apply {\n            isFillViewport = true\n        }\n        val content = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setPadding(dp(12), dp(12), dp(12), dp(14))\n        }\n\n        // === KORTTI 1: TÄNÄÄN ===\n        todayCard = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setPadding(dp(14), dp(12), dp(14), dp(14))\n        }\n\n        val todayTopRow = LinearLayout(context).apply {\n            orientation = HORIZONTAL\n            gravity = Gravity.CENTER_VERTICAL\n        }\n\n        txtTodayCaption = TextView(context).apply {\n            setTextColor(Color.parseColor("#94A3B8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n            setTypeface(null, Typeface.BOLD)\n            letterSpacing = 0.06f\n        }\n        todayTopRow.addView(txtTodayCaption, LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f))\n\n        progressBar = ProgressBar(context, null, android.R.attr.progressBarStyleSmall).apply {\n            isIndeterminate = true\n            visibility = View.GONE\n        }\n        todayTopRow.addView(progressBar, LayoutParams(dp(16), dp(16)))\n\n        txtStatus = TextView(context).apply {\n            setTextColor(Color.parseColor("#94A3B8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 11.5f)\n            setPadding(dp(6), 0, dp(8), 0)\n        }\n        todayTopRow.addView(txtStatus, LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT))\n\n        btnRefresh = Button(context).apply {\n            text = "↻"\n            setTextColor(Color.parseColor("#38BDF8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 15f)\n            setPadding(0, 0, 0, 0)\n            minHeight = 0\n            minimumHeight = dp(32)\n            setOnClickListener { loadState(forceNetwork = true, fromSwipe = false) }\n        }\n        todayTopRow.addView(btnRefresh, LayoutParams(dp(36), dp(32)))\n\n        todayCard.addView(todayTopRow, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        txtWorkingPill = TextView(context).apply {\n            setTextColor(Color.parseColor("#4ADE80"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f)\n            setTypeface(null, Typeface.BOLD)\n            background = UiStyleHelper.roundedBg(context, "#0F2E26", "#22C55E", 99f)\n            setPadding(dp(11), dp(4), dp(11), dp(4))\n            visibility = View.GONE\n        }\n        todayCard.addView(\n            txtWorkingPill,\n            LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT).apply {\n                topMargin = dp(8)\n                bottomMargin = dp(2)\n            }\n        )\n\n        txtShiftTimes = TextView(context).apply {\n            setTextColor(Color.WHITE)\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 24f)\n            setTypeface(null, Typeface.BOLD)\n            setPadding(0, dp(6), 0, dp(2))\n        }\n        todayCard.addView(txtShiftTimes, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        txtShiftWorkplace = TextView(context).apply {\n            setTextColor(Color.parseColor("#38BDF8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 16f)\n            setTypeface(null, Typeface.BOLD)\n            setPadding(0, dp(2), 0, 0)\n        }\n        todayCard.addView(txtShiftWorkplace, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        txtShiftDetails = TextView(context).apply {\n            setTextColor(Color.parseColor("#CBD5E1"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 14f)\n            setPadding(0, dp(2), 0, 0)\n        }\n        todayCard.addView(txtShiftDetails, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        // Vuoron edistymispalkki (näkyy sisäänleimattuna kun vuorolle on kellonajat)\n        shiftProgressContainer = LinearLayout(context).apply {\n            orientation = VERTICAL\n            visibility = View.GONE\n            setPadding(0, dp(10), 0, 0)\n        }\n        txtShiftRemaining = TextView(context).apply {\n            setTextColor(Color.parseColor("#94A3B8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n            setTypeface(null, Typeface.BOLD)\n            setPadding(0, 0, 0, dp(5))\n        }\n        shiftProgressContainer.addView(txtShiftRemaining, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        shiftProgressTrack = LinearLayout(context).apply {\n            orientation = HORIZONTAL\n            weightSum = 1f\n        }\n        shiftProgressFill = View(context)\n        shiftProgressRest = View(context)\n        shiftProgressTrack.addView(shiftProgressFill, LayoutParams(0, LayoutParams.MATCH_PARENT, 0f))\n        shiftProgressTrack.addView(shiftProgressRest, LayoutParams(0, LayoutParams.MATCH_PARENT, 1f))\n        shiftProgressContainer.addView(shiftProgressTrack, LayoutParams(LayoutParams.MATCH_PARENT, dp(5)))\n        todayCard.addView(shiftProgressContainer, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        txtPeriodBalance = TextView(context).apply {\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f)\n            setTypeface(null, Typeface.BOLD)\n            setPadding(dp(10), dp(7), dp(10), dp(7))\n            visibility = View.GONE\n        }\n        todayCard.addView(\n            txtPeriodBalance,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                topMargin = dp(10)\n            }\n        )\n\n        txtNextShift = TextView(context).apply {\n            setTextColor(Color.parseColor("#E2E8F0"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n            setPadding(dp(10), dp(8), dp(10), dp(8))\n            visibility = View.GONE\n        }\n        todayCard.addView(\n            txtNextShift,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                topMargin = dp(10)\n            }\n        )\n\n        content.addView(\n            todayCard,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                bottomMargin = dp(12)\n            }\n        )\n\n        // === KORTTI 2: LEIMAUS (nappi heti ylhäällä peukalon alla) ===\n        stampCard = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setPadding(dp(14), dp(12), dp(14), dp(10))\n        }\n\n        txtStampCaption = TextView(context).apply {\n            setTextColor(Color.parseColor("#94A3B8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n            setTypeface(null, Typeface.BOLD)\n            letterSpacing = 0.06f\n            setPadding(0, 0, 0, dp(10))\n        }\n        stampCard.addView(txtStampCaption, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        btnPunch = Button(context).apply {\n            isAllCaps = false\n            setTextColor(Color.WHITE)\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 17.5f)\n            setTypeface(null, Typeface.BOLD)\n            background = UiStyleHelper.rippleRoundedBg(context, "#15803D", "#22C55E", 10f, "#44FFFFFF")\n            setPadding(dp(12), dp(14), dp(12), dp(14))\n            minHeight = dp(54)\n            minimumHeight = dp(54)\n            setOnClickListener { handlePunchClick() }\n        }\n        stampCard.addView(btnPunch, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        optionsContainer = LinearLayout(context).apply {\n            orientation = VERTICAL\n            visibility = View.GONE\n            setPadding(0, dp(8), 0, dp(2))\n        }\n\n        // Kompakti syykoodi + lisätieto -avausrivi (TransitionManager-mikroanimaatio)\n        btnOptionsToggle = Button(context).apply {\n            isAllCaps = false\n            gravity = Gravity.START or Gravity.CENTER_VERTICAL\n            setTextColor(Color.parseColor("#CBD5E1"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n            setPadding(dp(12), dp(8), dp(12), dp(8))\n            minHeight = 0\n            minimumHeight = dp(38)\n            setOnClickListener {\n                try {\n                    TransitionManager.beginDelayedTransition(\n                        stampCard,\n                        AutoTransition().apply { duration = 170L }\n                    )\n                } catch (_: Exception) {\n                }\n                isOptionsExpanded = !isOptionsExpanded\n                optionsContainer.visibility = if (isOptionsExpanded) View.VISIBLE else View.GONE\n                updateOptionsToggleText()\n            }\n        }\n        stampCard.addView(\n            btnOptionsToggle,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                topMargin = dp(10)\n            }\n        )\n\n        txtReasonLabel = TextView(context).apply {\n            setTextColor(Color.parseColor("#CBD5E1"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f)\n            setPadding(0, 0, 0, dp(4))\n        }\n        optionsContainer.addView(txtReasonLabel, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        btnReasonSelector = Button(context).apply {\n            isAllCaps = false\n            gravity = Gravity.START or Gravity.CENTER_VERTICAL\n            setTextColor(Color.parseColor("#F1F5F9"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 14f)\n            setPadding(dp(12), dp(10), dp(12), dp(10))\n            setOnClickListener { showReasonCodeDialog() }\n        }\n        optionsContainer.addView(\n            btnReasonSelector,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                bottomMargin = dp(10)\n            }\n        )\n\n        txtCommentLabel = TextView(context).apply {\n            setTextColor(Color.parseColor("#CBD5E1"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f)\n            setPadding(0, 0, 0, dp(4))\n        }\n        optionsContainer.addView(txtCommentLabel, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        editComment = EditText(context).apply {\n            setTextColor(Color.WHITE)\n            setHintTextColor(Color.parseColor("#64748B"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 14f)\n            setPadding(dp(12), dp(10), dp(12), dp(10))\n            isSingleLine = true\n            filters = arrayOf(InputFilter.LengthFilter(255))\n            addTextChangedListener(object : TextWatcher {\n                override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}\n                override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {}\n                override fun afterTextChanged(s: Editable?) {\n                    updateOptionsToggleText()\n                }\n            })\n        }\n        optionsContainer.addView(\n            editComment,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                bottomMargin = dp(4)\n            }\n        )\n\n        stampCard.addView(optionsContainer, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        btnForgotten = Button(context).apply {\n            isAllCaps = false\n            setTextColor(Color.parseColor("#38BDF8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n            setTypeface(null, Typeface.BOLD)\n            background = UiStyleHelper.rippleTransparentBg(context, 8f)\n            gravity = Gravity.START or Gravity.CENTER_VERTICAL\n            setPadding(dp(4), dp(8), dp(10), dp(4))\n            minHeight = 0\n            minimumHeight = dp(36)\n            setOnClickListener {\n                val en = DemoModeHelper.isEnglish(context)\n                if (DemoModeHelper.isDemoEnabled(context)) {\n                    Toast.makeText(\n                        context,\n                        if (en) "Demo mode: Missing stamp form is disabled" else "Demotila: Puuttuvan leimauksen lisäys ei ole käytössä demossa",\n                        Toast.LENGTH_SHORT\n                    ).show()\n                } else {\n                    onOpenForgottenStampWeb()\n                }\n            }\n        }\n        stampCard.addView(\n            btnForgotten,\n            LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT).apply {\n                topMargin = dp(4)\n            }\n        )\n\n        content.addView(\n            stampCard,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                bottomMargin = dp(12)\n            }\n        )\n\n        // === KORTTI 3: VIIMEISIMMÄT LEIMAUKSET ===\n        historyCard = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setPadding(dp(14), dp(12), dp(14), dp(10))\n        }\n\n        txtLatestCaption = TextView(context).apply {\n            setTextColor(Color.parseColor("#94A3B8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n            setTypeface(null, Typeface.BOLD)\n            letterSpacing = 0.06f\n            setPadding(0, 0, 0, dp(8))\n        }\n        historyCard.addView(txtLatestCaption, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        stampsListContainer = LinearLayout(context).apply {\n            orientation = VERTICAL\n        }\n        historyCard.addView(stampsListContainer, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        btnShowMore = Button(context).apply {\n            isAllCaps = false\n            setTextColor(Color.parseColor("#38BDF8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n            setTypeface(null, Typeface.BOLD)\n            background = UiStyleHelper.rippleTransparentBg(context, 8f)\n            gravity = Gravity.START or Gravity.CENTER_VERTICAL\n            setPadding(dp(4), dp(8), dp(10), dp(4))\n            minHeight = 0\n            minimumHeight = dp(36)\n            visibility = View.GONE\n            setOnClickListener { loadMoreStamps() }\n        }\n        historyCard.addView(btnShowMore, LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT))\n\n        content.addView(historyCard, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n        scroll.addView(content, FrameLayout.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n        swipeRefresh.addView(scroll)\n        addView(swipeRefresh, LayoutParams(LayoutParams.MATCH_PARENT, 0, 1f))\n\n        applyThemeColors()\n    }\n\n    fun applyThemeColors() {\n        val bg = UiStyleHelper.bgHex(context)\n        val card = UiStyleHelper.cardHex(context)\n        val cardAlt = UiStyleHelper.cardAltHex(context)\n        val headerBtn = UiStyleHelper.headerCellHex(context)\n        val border = UiStyleHelper.borderHex(context)\n        val borderStrong = UiStyleHelper.borderStrongHex(context)\n\n        setBackgroundColor(Color.parseColor(bg))\n        UiStyleHelper.configureSwipeRefresh(swipeRefresh)\n        todayCard.background = UiStyleHelper.roundedBg(context, card, border, 12f)\n        stampCard.background = UiStyleHelper.roundedBg(context, card, border, 12f)\n        historyCard.background = UiStyleHelper.roundedBg(context, card, border, 12f)\n        btnRefresh.background = UiStyleHelper.rippleRoundedBg(context, headerBtn, borderStrong, 8f)\n        txtNextShift.background = UiStyleHelper.roundedBg(context, cardAlt, border, 8f)\n        btnOptionsToggle.background = UiStyleHelper.rippleRoundedBg(context, cardAlt, border, 8f)\n        btnReasonSelector.background = UiStyleHelper.rippleRoundedBg(context, cardAlt, borderStrong, 8f)\n        editComment.background = UiStyleHelper.roundedBg(context, cardAlt, borderStrong, 8f)\n        shiftProgressTrack.background = UiStyleHelper.roundedBg(context, cardAlt, border, 99f, 0)\n    }\n\n    override fun onAttachedToWindow() {\n        super.onAttachedToWindow()\n        tickerHandler.removeCallbacks(liveDurationRunnable)\n        tickerHandler.postDelayed(liveDurationRunnable, 30_000L)\n    }\n\n    override fun onDetachedFromWindow() {\n        tickerHandler.removeCallbacks(liveDurationRunnable)\n        super.onDetachedFromWindow()\n    }\n\n    fun onShow(forceNetwork: Boolean = false) {\n        applyThemeColors()\n        updateLocalizedLabels()\n        loadState(forceNetwork = forceNetwork, fromSwipe = false)\n    }\n\n    fun refreshFromNetwork() {\n        applyThemeColors()\n        updateLocalizedLabels()\n        loadState(forceNetwork = true, fromSwipe = false)\n    }\n\n    fun performAutoStamp(wantIn: Boolean, onFinished: () -> Unit) {\n        applyThemeColors()\n        updateLocalizedLabels()\n        val en = DemoModeHelper.isEnglish(context)\n        if (DemoModeHelper.isDemoEnabled(context)) {\n            val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n            val currentlyIn = prefs.getBoolean("demo_stamped_in", false)\n            val dirLabel = if (en) (if (wantIn) "In" else "Out") else (if (wantIn) "Sisään" else "Ulos")\n            if (wantIn != currentlyIn) {\n                recordDemoStamp(wantIn)\n                ShiftWidgetProvider.updateAllWidgets(context)\n                QuickStampTileService.requestTileUpdate(context)\n                Toast.makeText(\n                    context,\n                    if (en) "Demo mode: Clocked $dirLabel" else "Demotila: Leimattu ($dirLabel)",\n                    Toast.LENGTH_SHORT\n                ).show()\n            } else {\n                Toast.makeText(\n                    context,\n                    if (en) "Demo mode: Already clocked $dirLabel" else "Demotila: Olet jo leimannut tilaan $dirLabel",\n                    Toast.LENGTH_SHORT\n                ).show()\n            }\n            loadState(forceNetwork = false, fromSwipe = false)\n            postDelayed(onFinished, 1200L)\n            return\n        }\n\n        val expectedDir = if (wantIn) "IN" else "OUT"\n        val dirLabel = if (en) (if (wantIn) "In" else "Out") else (if (wantIn) "Sisään" else "Ulos")\n        setControlsBusy(true, if (en) "Stamping ($dirLabel)…" else "Leimataan ($dirLabel)…")\n\n        scope.launch {\n            val res = NumeronApiClient.performDirectStamp(\n                context = context,\n                currentState = null,\n                reasonCodeId = null,\n                comment = "",\n                expectedDirection = expectedDir,\n                onStatusUpdate = { msg -> post { txtStatus.text = msg } }\n            )\n            setControlsBusy(false, "")\n            when (res) {\n                is StampSubmitResult.Success -> {\n                    val nowMs = System.currentTimeMillis()\n                    lastSuccessfulStampMs = nowMs\n                    lastNetworkFetchMs = nowMs\n                    res.updatedState?.let {\n                        currentState = it\n                        selectedReasonCodeId = it.defaultReasonCode\n                        lastRenderedState = null\n                        renderState(it)\n                    }\n                    ShiftWidgetProvider.updateAllWidgets(context)\n                    QuickStampTileService.requestTileUpdate(context)\n                    Toast.makeText(\n                        context,\n                        if (en) "Stamp confirmed ($dirLabel)" else "Leimaus vahvistettu ($dirLabel)",\n                        Toast.LENGTH_SHORT\n                    ).show()\n                    postDelayed(onFinished, 1200L)\n                }\n                is StampSubmitResult.AlreadyInDirection -> {\n                    Toast.makeText(\n                        context,\n                        if (en) "Already clocked $dirLabel" else "Olet jo leimannut tilaan: $dirLabel",\n                        Toast.LENGTH_LONG\n                    ).show()\n                    loadState(forceNetwork = true, fromSwipe = false)\n                    postDelayed(onFinished, 1400L)\n                }\n                is StampSubmitResult.ValidationRejected -> {\n                    Toast.makeText(context, res.message, Toast.LENGTH_LONG).show()\n                    loadState(forceNetwork = true, fromSwipe = false)\n                }\n                is StampSubmitResult.Failed -> {\n                    Toast.makeText(context, res.message, Toast.LENGTH_LONG).show()\n                    loadState(forceNetwork = true, fromSwipe = false)\n                }\n            }\n        }\n    }\n\n    private fun updateLocalizedLabels() {\n        val en = DemoModeHelper.isEnglish(context)\n        txtTodayCaption.text = if (en) "TODAY" else "TÄNÄÄN"\n        txtStampCaption.text = if (en) "TIME STAMPING" else "LEIMAUS"\n        txtReasonLabel.text = if (en) "Reason code" else "Syykoodi"\n        txtCommentLabel.text = if (en) "Comment" else "Lisätiedot"\n        editComment.hint = if (en) "Write a note if needed" else "Kirjoita selite tarvittaessa"\n        btnForgotten.text = if (en) "+ Add missing stamp" else "+ Lisää puuttuva leimaus"\n        txtLatestCaption.text = if (en) "LATEST STAMPS" else "VIIMEISIMMÄT LEIMAUKSET"\n        btnShowMore.text = if (en) "Show more" else "Näytä lisää"\n        updateOptionsToggleText()\n    }\n\n    private fun updateOptionsToggleText() {\n        val en = DemoModeHelper.isEnglish(context)\n        val state = currentState\n        val activeRc = state?.reasonCodes?.firstOrNull { it.id == selectedReasonCodeId }\n            ?: state?.reasonCodes?.firstOrNull()\n        val rcLabel = activeRc?.label ?: (if (en) "Normal working time" else "Normaali työaika")\n        val comment = editComment.text?.toString()?.trim().orEmpty()\n        val arrow = if (isOptionsExpanded) "▴" else "▾"\n        val notePart = if (comment.isNotEmpty()) {\n            val shortNote = if (comment.length > 18) comment.take(18) + "…" else comment\n            "\\"$shortNote\\""\n        } else {\n            if (en) "+ Note" else "+ Lisätieto"\n        }\n        btnOptionsToggle.text = "$rcLabel  •  $notePart  $arrow"\n        btnReasonSelector.text = "$rcLabel  ▾"\n    }\n\n    private fun isSameVisualState(a: StampingPageState?, b: StampingPageState): Boolean {\n        if (a == null) return false\n        return a.shiftTimes == b.shiftTimes &&\n            a.shiftWorkplace == b.shiftWorkplace &&\n            a.shiftDetails == b.shiftDetails &&\n            a.nextDirection == b.nextDirection &&\n            a.punchButtonText == b.punchButtonText &&\n            a.defaultReasonCode == b.defaultReasonCode &&\n            a.reasonCodes == b.reasonCodes &&\n            a.latestStamps == b.latestStamps &&\n            a.hasMoreStamps == b.hasMoreStamps\n    }\n\n    private fun buildBalanceRenderKey(): String {\n        val enabled = PeriodBalanceManager.isEnabled(context)\n        val b = cachedPeriodBalance\n        return "$enabled|${PeriodBalanceManager.version}|${b?.periodStart}|${b?.diffMinutes}|${b?.plannedMinutes}|${b?.effectiveMinutes}"\n    }\n\n    private fun updatePeriodBalanceBanner() {\n        val en = DemoModeHelper.isEnglish(context)\n        val bal = cachedPeriodBalance\n        if (!PeriodBalanceManager.isEnabled(context) ||\n            DemoModeHelper.isDemoEnabled(context) ||\n            bal == null ||\n            bal.diffMinutes == 0\n        ) {\n            txtPeriodBalance.visibility = View.GONE\n            return\n        }\n        val shortFmt = DateTimeFormatter.ofPattern("d.M.")\n        val rangeStr = "${bal.periodStart.format(shortFmt)}–${bal.periodEnd.format(shortFmt)}"\n        val diffStr = PeriodBalanceManager.formatSignedExact(bal.diffMinutes, en)\n        val planH = PeriodBalanceManager.formatHoursDecimal(bal.plannedMinutes, en)\n        val effH = PeriodBalanceManager.formatHoursDecimal(bal.effectiveMinutes, en)\n        val prefix = if (en) "Period balance" else "Jakson saldo"\n        txtPeriodBalance.text = "$prefix ($rangeStr): $diffStr  ($planH → $effH h)"\n\n        if (bal.diffMinutes > 0) {\n            txtPeriodBalance.setTextColor(Color.parseColor("#4ADE80"))\n            txtPeriodBalance.background = UiStyleHelper.roundedBg(context, "#0F2E26", "#22C55E", 8f)\n        } else {\n            txtPeriodBalance.setTextColor(Color.parseColor("#FCA5A5"))\n            txtPeriodBalance.background = UiStyleHelper.roundedBg(context, "#3F1D24", "#F87171", 8f)\n        }\n        txtPeriodBalance.visibility = View.VISIBLE\n    }\n\n    private fun renderStateIfChanged(state: StampingPageState, forceRender: Boolean = false) {\n        val en = DemoModeHelper.isEnglish(context)\n        val isDemo = DemoModeHelper.isDemoEnabled(context)\n        val amoled = UiStyleHelper.isAmoled(context)\n        val balKey = buildBalanceRenderKey()\n        if (!forceRender &&\n            isSameVisualState(lastRenderedState, state) &&\n            lastRenderedNextShift == cachedNextShiftText &&\n            lastRenderedLangEn == en &&\n            lastRenderedDemo == isDemo &&\n            lastRenderedAmoled == amoled &&\n            lastRenderedBalanceKey == balKey\n        ) {\n            updateWorkingStatusPill()\n            updateOptionsToggleText()\n            return\n        }\n        lastRenderedState = state\n        lastRenderedNextShift = cachedNextShiftText\n        lastRenderedLangEn = en\n        lastRenderedDemo = isDemo\n        lastRenderedAmoled = amoled\n        lastRenderedBalanceKey = balKey\n        renderState(state)\n    }\n\n    private fun loadState(forceNetwork: Boolean, fromSwipe: Boolean = false) {\n        val en = DemoModeHelper.isEnglish(context)\n        val isDemo = DemoModeHelper.isDemoEnabled(context)\n        loadJob?.cancel()\n\n        val epoch = SessionCookieStore.sessionEpoch\n        if (epoch != lastSessionEpoch || lastRenderedDemo != isDemo) {\n            lastSessionEpoch = epoch\n            currentState = null\n            lastNetworkFetchMs = 0L\n            lastRenderedState = null\n            cachedNextShiftText = null\n            cachedPeriodBalance = null\n        }\n\n        if (isDemo) {\n            swipeRefresh.isRefreshing = false\n            progressBar.visibility = View.GONE\n            txtStatus.text = "Demo"\n            btnPunch.setOnClickListener { handlePunchClick() }\n            val demoState = buildDemoState()\n            currentState = demoState\n            selectedReasonCodeId = demoState.defaultReasonCode\n            renderStateIfChanged(demoState, forceRender = true)\n            return\n        }\n\n        val baseUrl = UrlNormalizer.getSavedBaseUrl(context)\n        if (baseUrl.isBlank()) {\n            swipeRefresh.isRefreshing = false\n            progressBar.visibility = View.GONE\n            txtStatus.text = ""\n            txtWorkingPill.visibility = View.GONE\n            shiftProgressContainer.visibility = View.GONE\n            txtPeriodBalance.visibility = View.GONE\n            txtNextShift.visibility = View.GONE\n            txtShiftTimes.visibility = View.VISIBLE\n            txtShiftTimes.text = if (en) "Welcome" else "Tervetuloa"\n            txtShiftWorkplace.visibility = View.VISIBLE\n            txtShiftWorkplace.text = if (en) "Set organization ID in Settings" else "Aseta organisaatiotunnus asetuksista"\n            txtShiftDetails.visibility = View.GONE\n            lastRenderedState = null\n            btnPunch.isEnabled = true\n            btnPunch.text = if (en) "Open Settings" else "Avaa asetukset"\n            btnPunch.background = UiStyleHelper.rippleRoundedBg(context, "#1982C4", "#38BDF8", 10f, "#44FFFFFF")\n            btnPunch.setOnClickListener { onOpenSettings() }\n            return\n        }\n\n        btnPunch.setOnClickListener { handlePunchClick() }\n\n        val existing = currentState\n        val nowMs = System.currentTimeMillis()\n        if (!forceNetwork && existing != null && !existing.fromCache && (nowMs - lastNetworkFetchMs) < 45_000L) {\n            swipeRefresh.isRefreshing = false\n            progressBar.visibility = View.GONE\n            txtStatus.text = UiStyleHelper.formatUpdatedLabel(context, lastNetworkFetchMs, isCache = false)\n            renderStateIfChanged(existing)\n            loadJob = scope.launch {\n                val bal = withContext(Dispatchers.IO) { PeriodBalanceManager.computeCurrentPeriodBalance(context) }\n                cachedPeriodBalance = bal\n                renderStateIfChanged(existing)\n            }\n            return\n        }\n\n        loadJob = scope.launch {\n            var cached: StampingPageState? = existing\n            var cachedAtMs: Long = lastNetworkFetchMs\n\n            val diskResult = withContext(Dispatchers.IO) {\n                val diskState = if (cached == null) NumeronApiClient.loadCachedStampingState(context) else cached\n                val diskMs = if (cached == null) NumeronApiClient.getStampingCacheSavedAtMs(context) else cachedAtMs\n                val nextShift = if (cachedNextShiftText == null) findNextUpcomingShiftText() else cachedNextShiftText\n                val bal = PeriodBalanceManager.computeCurrentPeriodBalance(context)\n                arrayOf<Any?>(diskState, diskMs, nextShift, bal)\n            }\n            cached = diskResult[0] as? StampingPageState\n            cachedAtMs = (diskResult[1] as? Long) ?: 0L\n            cachedNextShiftText = diskResult[2] as? String\n            cachedPeriodBalance = diskResult[3] as? PeriodBalanceResult\n            if (cached != null) {\n                if (currentState == null) {\n                    currentState = cached\n                    selectedReasonCodeId = cached.defaultReasonCode\n                }\n                renderStateIfChanged(currentState ?: cached)\n            }\n\n            val blocked = withContext(Dispatchers.IO) {\n                BackgroundAuthHelper.isCredentialBlocked(context)\n            }\n            if (blocked) {\n                swipeRefresh.isRefreshing = false\n                progressBar.visibility = View.GONE\n                txtStatus.text = if (en) "Check login" else "Tarkista tunnukset"\n                Toast.makeText(\n                    context,\n                    if (en) "Login failed – please check username and password in Settings"\n                    else "Kirjautuminen epäonnistui – tarkista käyttäjätunnus ja salasana asetuksista",\n                    Toast.LENGTH_LONG\n                ).show()\n                return@launch\n            }\n\n            if (!fromSwipe) {\n                progressBar.visibility = View.VISIBLE\n            }\n            txtStatus.text = if (cached != null && !forceNetwork) {\n                if (en) "Updating…" else "Päivitetään…"\n            } else {\n                if (en) "Loading…" else "Ladataan…"\n            }\n\n            val fresh = NumeronApiClient.fetchStampingState(context, forceRefreshSession = false)\n            swipeRefresh.isRefreshing = false\n            progressBar.visibility = View.GONE\n            if (fresh != null) {\n                val fetchedAt = System.currentTimeMillis()\n                lastNetworkFetchMs = fetchedAt\n                currentState = fresh\n                selectedReasonCodeId = fresh.defaultReasonCode\n                if (fresh.shiftTimes.isEmpty() && cachedNextShiftText == null) {\n                    cachedNextShiftText = withContext(Dispatchers.IO) { findNextUpcomingShiftText() }\n                }\n                txtStatus.text = UiStyleHelper.formatUpdatedLabel(context, fetchedAt, isCache = false)\n                renderStateIfChanged(fresh)\n                ShiftWidgetProvider.updateAllWidgets(context)\n                QuickStampTileService.requestTileUpdate(context)\n            } else {\n                txtStatus.text = if (cached != null) {\n                    UiStyleHelper.formatUpdatedLabel(context, cachedAtMs, isCache = true)\n                        .ifEmpty { if (en) "Offline cache" else "Välimuisti" }\n                } else {\n                    if (en) "Load failed" else "Lataus epäonnistui"\n                }\n            }\n        }\n    }\n\n    private fun renderState(state: StampingPageState) {\n        val en = DemoModeHelper.isEnglish(context)\n\n        updateWorkingStatusPill()\n        updatePeriodBalanceBanner()\n\n        if (state.shiftTimes.isNotEmpty()) {\n            txtShiftTimes.visibility = View.VISIBLE\n            txtShiftTimes.text = state.shiftTimes\n        } else {\n            txtShiftTimes.visibility = View.GONE\n        }\n\n        if (state.shiftWorkplace.isNotEmpty()) {\n            txtShiftWorkplace.visibility = View.VISIBLE\n            txtShiftWorkplace.text = state.shiftWorkplace\n        } else if (state.shiftTimes.isEmpty()) {\n            txtShiftWorkplace.visibility = View.VISIBLE\n            txtShiftWorkplace.text = if (en) "No scheduled shift today" else "Ei suunniteltua työvuoroa tänään"\n        } else {\n            txtShiftWorkplace.visibility = View.GONE\n        }\n\n        if (state.shiftDetails.isNotEmpty()) {\n            txtShiftDetails.visibility = View.VISIBLE\n            txtShiftDetails.text = state.shiftDetails\n        } else {\n            txtShiftDetails.visibility = View.GONE\n        }\n\n        // Vapaapäivänä näytetään seuraava tuleva vuoro kalenterivälimuistista (luettu IO-säikeessä)\n        if (state.shiftTimes.isEmpty()) {\n            val nextInfo = cachedNextShiftText\n            if (nextInfo != null) {\n                txtNextShift.text = nextInfo\n                txtNextShift.visibility = View.VISIBLE\n            } else {\n                txtNextShift.visibility = View.GONE\n            }\n        } else {\n            txtNextShift.visibility = View.GONE\n        }\n\n        updateOptionsToggleText()\n\n        val isOutNext = state.nextDirection.equals("OUT", ignoreCase = true)\n        btnPunch.isEnabled = !isSubmitting && (state.nextDirection == "IN" || state.nextDirection == "OUT")\n        btnPunch.text = state.punchButtonText.ifEmpty {\n            if (en) {\n                if (isOutNext) "Clock Out" else "Clock In"\n            } else {\n                if (isOutNext) "Leimaa Ulos" else "Leimaa Sisään"\n            }\n        }\n        btnPunch.background = if (isOutNext) {\n            UiStyleHelper.rippleRoundedBg(context, "#B91C1C", "#F87171", 10f, "#44FFFFFF")\n        } else {\n            UiStyleHelper.rippleRoundedBg(context, "#15803D", "#22C55E", 10f, "#44FFFFFF")\n        }\n\n        renderStampsTable(state.latestStamps)\n        btnShowMore.visibility = if (state.hasMoreStamps) View.VISIBLE else View.GONE\n    }\n\n    private fun parseStampRowDateTime(row: StampHistoryRow): LocalDateTime? {\n        val timeMatch = Regex("(\\\\d{1,2}):(\\\\d{2})").find(row.timeText.trim()) ?: return null\n        val hh = timeMatch.groupValues[1].toIntOrNull() ?: return null\n        val mm = timeMatch.groupValues[2].toIntOrNull() ?: return null\n        val time = try {\n            LocalTime.of(hh, mm)\n        } catch (_: Exception) {\n            return null\n        }\n\n        val dayClean = row.dayText.trim().lowercase()\n        val today = LocalDate.now()\n        val date = when {\n            dayClean == "tänään" || dayClean == "today" || dayClean == "idag" -> today\n            dayClean == "eilen" || dayClean == "yesterday" || dayClean == "igår" -> today.minusDays(1)\n            else -> {\n                val m = Regex("(\\\\d{1,2})\\\\.(\\\\d{1,2})\\\\.(\\\\d{4})").find(dayClean)\n                if (m != null) {\n                    try {\n                        LocalDate.of(m.groupValues[3].toInt(), m.groupValues[2].toInt(), m.groupValues[1].toInt())\n                    } catch (_: Exception) {\n                        null\n                    }\n                } else {\n                    null\n                }\n            }\n        } ?: return null\n\n        return LocalDateTime.of(date, time)\n    }\n\n    private fun parseShiftBounds(shiftTimes: String, referenceInDt: LocalDateTime?): Pair<LocalDateTime, LocalDateTime>? {\n        val m = Regex("(\\\\d{1,2}):(\\\\d{2})\\\\s*[-–—]\\\\s*(\\\\d{1,2}):(\\\\d{2})").find(shiftTimes) ?: return null\n        val sTime = try {\n            LocalTime.of(m.groupValues[1].toInt(), m.groupValues[2].toInt())\n        } catch (_: Exception) {\n            return null\n        }\n        val eTime = try {\n            LocalTime.of(m.groupValues[3].toInt(), m.groupValues[4].toInt())\n        } catch (_: Exception) {\n            return null\n        }\n        val baseDate = referenceInDt?.toLocalDate() ?: LocalDate.now()\n        var startDt = LocalDateTime.of(baseDate, sTime)\n        var endDt = LocalDateTime.of(if (eTime.isBefore(sTime)) baseDate.plusDays(1) else baseDate, eTime)\n        val now = LocalDateTime.now()\n        // Jos yövuoro alkoi eilen ja päättyy tänä aamuna\n        if (referenceInDt == null && eTime.isBefore(sTime) && now.toLocalTime().isBefore(eTime.plusHours(2))) {\n            startDt = startDt.minusDays(1)\n            endDt = endDt.minusDays(1)\n        }\n        return startDt to endDt\n    }\n\n    private fun updateShiftProgressBar(state: StampingPageState, inDt: LocalDateTime?) {\n        val en = DemoModeHelper.isEnglish(context)\n        if (!state.nextDirection.equals("OUT", ignoreCase = true) || state.shiftTimes.isBlank()) {\n            shiftProgressContainer.visibility = View.GONE\n            return\n        }\n        val bounds = parseShiftBounds(state.shiftTimes, inDt)\n        if (bounds == null) {\n            shiftProgressContainer.visibility = View.GONE\n            return\n        }\n        val (shiftStart, shiftEnd) = bounds\n        val totalMins = Duration.between(shiftStart, shiftEnd).toMinutes()\n        if (totalMins <= 0L) {\n            shiftProgressContainer.visibility = View.GONE\n            return\n        }\n        val now = LocalDateTime.now()\n        val elapsedMins = Duration.between(shiftStart, now).toMinutes()\n        val remainingMins = Duration.between(now, shiftEnd).toMinutes()\n        val ratio = (elapsedMins.toFloat() / totalMins.toFloat()).coerceIn(0f, 1f)\n        val pct = (ratio * 100f).toInt().coerceIn(0, 100)\n\n        fun fmtDur(mins: Long): String {\n            val h = mins / 60L\n            val m = mins % 60L\n            return if (en) {\n                if (h > 0L) "${h}h ${m}m" else "${m}m"\n            } else {\n                if (h > 0L) "$h h $m min" else "$m min"\n            }\n        }\n\n        val statusLabel = when {\n            remainingMins > 0L -> {\n                if (en) "Remaining ${fmtDur(remainingMins)} • $pct%" else "Jäljellä ${fmtDur(remainingMins)} • $pct %"\n            }\n            remainingMins == 0L -> {\n                if (en) "Shift complete • 100%" else "Vuoro täynnä • 100 %"\n            }\n            else -> {\n                val over = -remainingMins\n                if (en) "Overtime +${fmtDur(over)}" else "Ylitöillä +${fmtDur(over)}"\n            }\n        }\n        txtShiftRemaining.text = statusLabel\n        val fillColorHex = when {\n            remainingMins < 0L -> "#F59E0B"\n            ratio >= 0.85f -> "#22C55E"\n            else -> "#38BDF8"\n        }\n        shiftProgressFill.background = UiStyleHelper.roundedBg(context, fillColorHex, fillColorHex, 99f, 0)\n\n        val fillWeight = ratio.coerceIn(0.02f, 1f)\n        (shiftProgressFill.layoutParams as LayoutParams).weight = fillWeight\n        (shiftProgressRest.layoutParams as LayoutParams).weight = (1f - fillWeight).coerceAtLeast(0f)\n        shiftProgressTrack.requestLayout()\n        shiftProgressContainer.visibility = View.VISIBLE\n    }\n\n    private fun updateWorkingStatusPill() {\n        val state = currentState\n        if (state == null || !state.nextDirection.equals("OUT", ignoreCase = true)) {\n            txtWorkingPill.visibility = View.GONE\n            shiftProgressContainer.visibility = View.GONE\n            return\n        }\n        val en = DemoModeHelper.isEnglish(context)\n        val latestIn = state.latestStamps.firstOrNull { it.isIn }\n        val inDt = latestIn?.let { parseStampRowDateTime(it) }\n        val now = LocalDateTime.now()\n\n        updateShiftProgressBar(state, inDt)\n\n        if (inDt != null && !inDt.isAfter(now.plusMinutes(2))) {\n            val mins = Duration.between(inDt, now).toMinutes().coerceAtLeast(0L)\n            if (mins <= 20L * 60L) {\n                val h = mins / 60L\n                val m = mins % 60L\n                val timeStr = inDt.format(DateTimeFormatter.ofPattern("HH:mm"))\n                val durStr = if (en) {\n                    if (h > 0L) "${h}h ${m}m" else "${m}m"\n                } else {\n                    if (h > 0L) "$h h $m min" else "$m min"\n                }\n                txtWorkingPill.text = if (en) {\n                    "● Clocked in • $timeStr • $durStr"\n                } else {\n                    "● Töissä • sisään klo $timeStr • $durStr"\n                }\n                txtWorkingPill.visibility = View.VISIBLE\n                return\n            }\n        }\n\n        txtWorkingPill.text = if (en) "● Clocked in" else "● Töissä (leimattu sisään)"\n        txtWorkingPill.visibility = View.VISIBLE\n    }\n\n    private fun findNextUpcomingShiftText(): String? {\n        val en = DemoModeHelper.isEnglish(context)\n        val shifts = if (DemoModeHelper.isDemoEnabled(context)) {\n            DemoModeHelper.generateDemoWorkShifts(context)\n        } else {\n            CalendarSyncHelper.loadCachedShifts(context)\n        } ?: return null\n\n        val now = LocalDateTime.now()\n        val next = shifts\n            .filter { !it.isAllDayLeave && it.start.isAfter(now) }\n            .minByOrNull { it.start }\n            ?: return null\n\n        val fiDow = arrayOf("Ma", "Ti", "Ke", "To", "Pe", "La", "Su")\n        val enDow = arrayOf("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")\n        val dow = (if (en) enDow else fiDow)[next.start.dayOfWeek.value - 1]\n        val datePart = next.start.format(DateTimeFormatter.ofPattern("d.M."))\n        val timePart = "${next.start.format(DateTimeFormatter.ofPattern("HH:mm"))}–${next.end.format(DateTimeFormatter.ofPattern("HH:mm"))}"\n        val locPart = next.location.takeIf { it.isNotBlank() }?.let { " • $it" }.orEmpty()\n        return if (en) {\n            "Next shift: $dow $datePart $timePart$locPart"\n        } else {\n            "Seuraava vuoro: $dow $datePart klo $timePart$locPart"\n        }\n    }\n\n    private fun renderStampsTable(rows: List<StampHistoryRow>) {\n        stampsListContainer.removeAllViews()\n        val en = DemoModeHelper.isEnglish(context)\n        val isDemo = DemoModeHelper.isDemoEnabled(context)\n        val dividerColor = Color.parseColor(UiStyleHelper.borderHex(context))\n\n        if (rows.isEmpty()) {\n            stampsListContainer.addView(\n                TextView(context).apply {\n                    text = if (en) "No recent stamps" else "Ei viimeisimpiä leimauksia"\n                    setTextColor(Color.parseColor("#94A3B8"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n                    setPadding(0, dp(6), 0, dp(6))\n                }\n            )\n            return\n        }\n\n        for (i in rows.indices) {\n            val row = rows[i]\n            if (i > 0) {\n                val divider = View(context).apply {\n                    setBackgroundColor(dividerColor)\n                }\n                stampsListContainer.addView(divider, LayoutParams(LayoutParams.MATCH_PARENT, 1))\n            }\n\n            val rowView = LinearLayout(context).apply {\n                orientation = HORIZONTAL\n                gravity = Gravity.CENTER_VERTICAL\n                setPadding(dp(4), dp(11), dp(4), dp(11))\n                if (!isDemo && row.rowId.isNotEmpty()) {\n                    background = UiStyleHelper.rippleTransparentBg(context, 8f)\n                    setOnClickListener { onOpenEditStampWeb(row.rowId) }\n                }\n            }\n\n            val dayTv = TextView(context).apply {\n                text = row.dayText\n                setTextColor(Color.parseColor("#E2E8F0"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 14f)\n            }\n            rowView.addView(dayTv, LayoutParams(0, LayoutParams.WRAP_CONTENT, 1.2f))\n\n            val timeTv = TextView(context).apply {\n                text = row.timeText\n                setTextColor(Color.WHITE)\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 14.5f)\n                setTypeface(null, Typeface.BOLD)\n            }\n            rowView.addView(timeTv, LayoutParams(0, LayoutParams.WRAP_CONTENT, 0.8f))\n\n            val badgeBg = if (row.isIn) "#122B22" else "#3F1D24"\n            val badgeBorder = if (row.isIn) "#22C55E" else "#F87171"\n            val badgeFg = if (row.isIn) "#4ADE80" else "#F87171"\n            val dirBadge = TextView(context).apply {\n                text = row.directionText\n                setTextColor(Color.parseColor(badgeFg))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n                setTypeface(null, Typeface.BOLD)\n                background = UiStyleHelper.roundedBg(context, badgeBg, badgeBorder, 99f)\n                setPadding(dp(10), dp(3), dp(10), dp(3))\n            }\n            rowView.addView(dirBadge, LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT))\n\n            if (!isDemo && row.rowId.isNotEmpty()) {\n                val arrow = TextView(context).apply {\n                    text = "›"\n                    setTextColor(Color.parseColor("#64748B"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 18f)\n                    setPadding(dp(10), 0, dp(2), 0)\n                }\n                rowView.addView(arrow, LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT))\n            }\n\n            stampsListContainer.addView(rowView, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n        }\n    }\n\n    private fun showReasonCodeDialog() {\n        val codes = currentState?.reasonCodes.orEmpty()\n        if (codes.isEmpty()) return\n        val en = DemoModeHelper.isEnglish(context)\n        val labels = codes.map { it.label }.toTypedArray()\n        val checkedIdx = codes.indexOfFirst { it.id == selectedReasonCodeId }.coerceAtLeast(0)\n\n        AlertDialog.Builder(context)\n            .setTitle(if (en) "Select reason code" else "Valitse syykoodi")\n            .setSingleChoiceItems(labels, checkedIdx) { dialog, which ->\n                val chosen = codes[which]\n                selectedReasonCodeId = chosen.id\n                updateOptionsToggleText()\n                dialog.dismiss()\n            }\n            .setNegativeButton(if (en) "Cancel" else "Peruuta", null)\n            .show()\n    }\n\n    private fun recentStampTimeLabel(): String? {\n        val nowMs = System.currentTimeMillis()\n        if (lastSuccessfulStampMs > 0L && (nowMs - lastSuccessfulStampMs) in 0L..(4L * 60_000L)) {\n            return LocalTime.now().format(DateTimeFormatter.ofPattern("HH:mm"))\n        }\n        val latest = currentState?.latestStamps?.firstOrNull() ?: return null\n        val dt = parseStampRowDateTime(latest) ?: return null\n        val diffMins = Duration.between(dt, LocalDateTime.now()).toMinutes()\n        return if (diffMins in 0L..4L) dt.format(DateTimeFormatter.ofPattern("HH:mm")) else null\n    }\n\n    private fun handlePunchClick() {\n        if (isSubmitting) return\n        btnPunch.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY)\n\n        val recentTime = recentStampTimeLabel()\n        if (recentTime != null && !DemoModeHelper.isDemoEnabled(context)) {\n            val en = DemoModeHelper.isEnglish(context)\n            AlertDialog.Builder(context)\n                .setTitle(if (en) "Confirm stamp" else "Vahvista leimaus")\n                .setMessage(\n                    if (en) "You recorded a stamp just a moment ago ($recentTime). Do you want to stamp again?"\n                    else "Teit leimauksen juuri äsken (klo $recentTime). Haluatko varmasti leimata uudelleen?"\n                )\n                .setPositiveButton(if (en) "Stamp" else "Leimaa") { _, _ ->\n                    executePunchNow()\n                }\n                .setNegativeButton(if (en) "Cancel" else "Peruuta", null)\n                .show()\n            return\n        }\n\n        executePunchNow()\n    }\n\n    private fun executePunchNow() {\n        val en = DemoModeHelper.isEnglish(context)\n\n        if (DemoModeHelper.isDemoEnabled(context)) {\n            val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n            val currentlyIn = prefs.getBoolean("demo_stamped_in", false)\n            val wantIn = !currentlyIn\n            recordDemoStamp(wantIn)\n            editComment.setText("")\n            ShiftWidgetProvider.updateAllWidgets(context)\n            QuickStampTileService.requestTileUpdate(context)\n            val dirLabel = if (en) (if (wantIn) "In" else "Out") else (if (wantIn) "Sisään" else "Ulos")\n            Toast.makeText(\n                context,\n                if (en) "Demo stamp recorded ($dirLabel)" else "Demoleimaus tallennettu ($dirLabel)",\n                Toast.LENGTH_SHORT\n            ).show()\n            loadState(forceNetwork = false, fromSwipe = false)\n            return\n        }\n\n        val state = currentState\n        val comment = editComment.text?.toString()?.trim().orEmpty()\n        setControlsBusy(true, if (en) "Recording stamp…" else "Lähetetään leimausta…")\n\n        scope.launch {\n            val result = NumeronApiClient.performDirectStamp(\n                context = context,\n                currentState = state,\n                reasonCodeId = selectedReasonCodeId,\n                comment = comment,\n                expectedDirection = null,\n                onStatusUpdate = { msg -> post { txtStatus.text = msg } }\n            )\n            setControlsBusy(false, "")\n\n            when (result) {\n                is StampSubmitResult.Success -> {\n                    lastSuccessfulStampMs = System.currentTimeMillis()\n                    lastNetworkFetchMs = lastSuccessfulStampMs\n                    editComment.setText("")\n                    isOptionsExpanded = false\n                    optionsContainer.visibility = View.GONE\n                    val dirLabel = if (en) {\n                        if (result.directionUsed == "IN") "In" else "Out"\n                    } else {\n                        if (result.directionUsed == "IN") "Sisään" else "Ulos"\n                    }\n                    result.updatedState?.let {\n                        currentState = it\n                        selectedReasonCodeId = it.defaultReasonCode\n                        txtStatus.text = UiStyleHelper.formatUpdatedLabel(context, lastSuccessfulStampMs, isCache = false)\n                        renderStateIfChanged(it, forceRender = true)\n                    }\n                    ShiftWidgetProvider.updateAllWidgets(context)\n                    QuickStampTileService.requestTileUpdate(context)\n                    Toast.makeText(\n                        context,\n                        if (en) "Stamp confirmed ($dirLabel)" else "Leimaus vahvistettu ($dirLabel)",\n                        Toast.LENGTH_SHORT\n                    ).show()\n                }\n                is StampSubmitResult.AlreadyInDirection -> {\n                    loadState(forceNetwork = true, fromSwipe = false)\n                }\n                is StampSubmitResult.ValidationRejected -> {\n                    AlertDialog.Builder(context)\n                        .setTitle(if (en) "Stamp not saved" else "Leimausta ei tallennettu")\n                        .setMessage(result.message)\n                        .setPositiveButton("OK", null)\n                        .show()\n                    loadState(forceNetwork = true, fromSwipe = false)\n                }\n                is StampSubmitResult.Failed -> {\n                    Toast.makeText(context, result.message, Toast.LENGTH_LONG).show()\n                    loadState(forceNetwork = true, fromSwipe = false)\n                }\n            }\n        }\n    }\n\n    private fun loadMoreStamps() {\n        val state = currentState ?: return\n        val en = DemoModeHelper.isEnglish(context)\n        val nextTake = state.currentTake + 6\n        btnShowMore.isEnabled = false\n        progressBar.visibility = View.VISIBLE\n        txtStatus.text = if (en) "Loading more…" else "Haetaan lisää…"\n\n        scope.launch {\n            val res = NumeronApiClient.fetchMoreStamps(context, nextTake, state.getMoreStampsUrl)\n            progressBar.visibility = View.GONE\n            btnShowMore.isEnabled = true\n\n            if (res != null) {\n                val (newRows, hasMore) = res\n                val updated = state.copy(\n                    latestStamps = newRows,\n                    hasMoreStamps = hasMore,\n                    currentTake = newRows.size.coerceAtLeast(nextTake)\n                )\n                val updatedAt = System.currentTimeMillis()\n                lastNetworkFetchMs = updatedAt\n                currentState = updated\n                withContext(Dispatchers.IO) {\n                    NumeronApiClient.saveCachedStampingState(context, updated)\n                }\n                txtStatus.text = UiStyleHelper.formatUpdatedLabel(context, updatedAt, isCache = false)\n                renderStateIfChanged(updated, forceRender = true)\n            } else {\n                txtStatus.text = ""\n                Toast.makeText(\n                    context,\n                    if (en) "Could not load more stamps" else "Lisäleimausten haku epäonnistui",\n                    Toast.LENGTH_SHORT\n                ).show()\n            }\n        }\n    }\n\n    private fun setControlsBusy(busy: Boolean, statusMsg: String) {\n        isSubmitting = busy\n        btnPunch.isEnabled = !busy\n        btnOptionsToggle.isEnabled = !busy\n        btnReasonSelector.isEnabled = !busy\n        editComment.isEnabled = !busy\n        progressBar.visibility = if (busy) View.VISIBLE else View.GONE\n        txtStatus.text = statusMsg\n    }\n\n    private fun buildDemoState(): StampingPageState {\n        val en = DemoModeHelper.isEnglish(context)\n        val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n        val isIn = prefs.getBoolean("demo_stamped_in", false)\n        val yest = LocalDate.now().minusDays(1).format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))\n        val defaultHist = "$yest | 14:30 | Ulos\\n$yest | 07:00 | Sisään"\n        val rawHist = prefs.getString("demo_stamp_history", defaultHist) ?: defaultHist\n        val todayStr = LocalDate.now().format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))\n\n        val rows = rawHist.lineSequence()\n            .map { it.trim() }\n            .filter { it.isNotEmpty() }\n            .mapNotNull { line ->\n                val parts = line.split("|").map { it.trim() }\n                if (parts.size < 3) return@mapNotNull null\n                val dayDisplay = if (parts[0] == todayStr) (if (en) "Today" else "Tänään") else parts[0]\n                val isRowIn = parts[2].equals("Sisään", true) || parts[2].equals("In", true)\n                val dirLabel = if (en) (if (isRowIn) "In" else "Out") else (if (isRowIn) "Sisään" else "Ulos")\n                StampHistoryRow("", dayDisplay, parts[1], dirLabel, isRowIn, "")\n            }\n            .toList()\n\n        return StampingPageState(\n            shiftTimes = "07:00 - 14:30",\n            shiftWorkplace = if (en) "Demo Ward A" else "Demo-osasto A",\n            shiftDetails = if (en) "Morning shift • Nurse" else "Aamuvuoro • Hoitaja",\n            nextDirection = if (isIn) "OUT" else "IN",\n            punchButtonText = if (en) {\n                if (isIn) "Clock Out" else "Clock In"\n            } else {\n                if (isIn) "Leimaa Ulos" else "Leimaa Sisään"\n            },\n            defaultReasonCode = 0,\n            reasonCodes = listOf(\n                StampReasonCode(0, if (en) "Normal working time" else "Normaali työaika"),\n                StampReasonCode(7, if (en) "Work matter" else "Työasia")\n            ),\n            latestStamps = rows,\n            hasMoreStamps = false,\n            currentTake = rows.size,\n            verificationToken = "",\n            saveStampUrl = "",\n            validateStampSaveUrl = "",\n            getMoreStampsUrl = "",\n            fromCache = false\n        )\n    }\n\n    private fun recordDemoStamp(wantIn: Boolean) {\n        val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n        val nowDate = LocalDate.now().format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))\n        val nowTime = LocalTime.now().format(DateTimeFormatter.ofPattern("HH:mm"))\n        val yest = LocalDate.now().minusDays(1).format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))\n        val defaultHistory = "$yest | 14:30 | Ulos\\n$yest | 07:00 | Sisään"\n        val oldHistory = prefs.getString("demo_stamp_history", defaultHistory) ?: defaultHistory\n        val dirFi = if (wantIn) "Sisään" else "Ulos"\n        val newHistory = "$nowDate | $nowTime | $dirFi\\n$oldHistory"\n        prefs.edit()\n            .putBoolean("demo_stamped_in", wantIn)\n            .putString("demo_stamp_history", newHistory)\n            .apply()\n    }\n\n    private fun dp(value: Int): Int = UiStyleHelper.dp(context, value)\n}\n'

NATIVE_SHIFTS_VIEW_KT = 'package fi.numeron.vuorovahti\n\nimport android.content.Context\nimport android.content.Intent\nimport android.graphics.Color\nimport android.graphics.Typeface\nimport android.graphics.drawable.GradientDrawable\nimport android.provider.AlarmClock\nimport android.text.SpannableStringBuilder\nimport android.text.Spanned\nimport android.text.TextUtils\nimport android.text.style.ForegroundColorSpan\nimport android.text.style.StyleSpan\nimport android.util.TypedValue\nimport android.view.Gravity\nimport android.view.MotionEvent\nimport android.view.View\nimport android.widget.Button\nimport android.widget.FrameLayout\nimport android.widget.LinearLayout\nimport android.widget.ProgressBar\nimport android.widget.ScrollView\nimport android.widget.TextView\nimport android.widget.Toast\nimport androidx.appcompat.app.AlertDialog\nimport androidx.swiperefreshlayout.widget.SwipeRefreshLayout\nimport kotlinx.coroutines.CoroutineScope\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.Job\nimport kotlinx.coroutines.launch\nimport kotlinx.coroutines.withContext\nimport java.net.URLEncoder\nimport java.time.DayOfWeek\nimport java.time.Duration\nimport java.time.LocalDate\nimport java.time.LocalDateTime\nimport java.time.LocalTime\nimport java.time.YearMonth\nimport java.time.format.DateTimeFormatter\nimport java.time.temporal.ChronoUnit\nimport java.time.temporal.WeekFields\nimport kotlin.math.abs\n\nclass NativeShiftsView(\n    private val context: Context,\n    private val scope: CoroutineScope,\n    private val onOpenWebUrl: (url: String, title: String) -> Unit\n) : LinearLayout(context) {\n\n    private var displayedMonth: YearMonth = YearMonth.now()\n    private var currentData: MonthDisplayData? = null\n    private var adjacentDayMap: Map<LocalDate, CalendarDisplayDay> = emptyMap()\n    private var adjacentLoadedMonths: Set<String> = emptySet()\n    private var currentMonthLoaded: Boolean = false\n    private var loadJob: Job? = null\n    private var prefetchJob: Job? = null\n    private var lastSessionEpoch: Long = -1L\n    private var lastRenderedRenderKey: String? = null\n    private var lastRenderedData: MonthDisplayData? = null\n    private var lastRenderedAdjacentSize: Int = -1\n    private val memoryMonths = LinkedHashMap<YearMonth, Pair<MonthDisplayData, Long>>()\n\n    private var swipeDownX: Float = 0f\n    private var swipeDownY: Float = 0f\n\n    private val headerCard: LinearLayout\n    private val swipeRefresh: SwipeRefreshLayout\n    private val txtMonthTitle: TextView\n    private val btnPrev: Button\n    private val btnNext: Button\n    private val btnToday: Button\n    private val btnRefresh: Button\n    private val btnShare: Button\n    private val progressBar: ProgressBar\n    private val txtStatus: TextView\n    private val gridContainer: LinearLayout\n    private val txtMonthSummary: TextView\n\n    private val fiMonths = arrayOf(\n        "Tammikuu", "Helmikuu", "Maaliskuu", "Huhtikuu", "Toukokuu", "Kesäkuu",\n        "Heinäkuu", "Elokuu", "Syyskuu", "Lokakuu", "Marraskuu", "Joulukuu"\n    )\n    private val enMonths = arrayOf(\n        "January", "February", "March", "April", "May", "June",\n        "July", "August", "September", "October", "November", "December"\n    )\n    private val fiShortMonths = arrayOf(\n        "Tammi", "Helmi", "Maalis", "Huhti", "Touko", "Kesä",\n        "Heinä", "Elo", "Syys", "Loka", "Marras", "Joulu"\n    )\n    private val enShortMonths = arrayOf(\n        "Jan", "Feb", "Mar", "Apr", "May", "Jun",\n        "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"\n    )\n\n    init {\n        orientation = VERTICAL\n        setPadding(dp(8), dp(8), dp(8), dp(4))\n\n        // Yläkortti: kuukausivalitsin + pikapainikkeet\n        headerCard = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setPadding(dp(10), dp(10), dp(10), dp(8))\n        }\n\n        val navRow = LinearLayout(context).apply {\n            orientation = HORIZONTAL\n            gravity = Gravity.CENTER_VERTICAL\n        }\n\n        btnPrev = Button(context).apply {\n            text = "◀"\n            setTextColor(Color.parseColor("#38BDF8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 16f)\n            setPadding(0, 0, 0, 0)\n            setOnClickListener {\n                displayedMonth = displayedMonth.minusMonths(1)\n                animateMonthSlide(-1)\n                loadMonth(forceNetwork = false, fromSwipe = false)\n            }\n        }\n        navRow.addView(btnPrev, LayoutParams(dp(44), dp(38)))\n\n        txtMonthTitle = TextView(context).apply {\n            setTextColor(Color.parseColor("#F1F5F9"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 17f)\n            setTypeface(null, Typeface.BOLD)\n            gravity = Gravity.CENTER\n            setPadding(dp(12), dp(7), dp(12), dp(7))\n            setOnClickListener { showMonthJumpDialog() }\n        }\n        navRow.addView(\n            txtMonthTitle,\n            LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f).apply {\n                marginStart = dp(10)\n                marginEnd = dp(10)\n            }\n        )\n\n        btnNext = Button(context).apply {\n            text = "▶"\n            setTextColor(Color.parseColor("#38BDF8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 16f)\n            setPadding(0, 0, 0, 0)\n            setOnClickListener {\n                displayedMonth = displayedMonth.plusMonths(1)\n                animateMonthSlide(1)\n                loadMonth(forceNetwork = false, fromSwipe = false)\n            }\n        }\n        navRow.addView(btnNext, LayoutParams(dp(44), dp(38)))\n\n        headerCard.addView(navRow, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        val actionRow = LinearLayout(context).apply {\n            orientation = HORIZONTAL\n            gravity = Gravity.CENTER_VERTICAL\n            setPadding(0, dp(8), 0, 0)\n        }\n\n        btnToday = Button(context).apply {\n            isAllCaps = false\n            setTextColor(Color.parseColor("#E2E8F0"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n            setPadding(dp(10), dp(4), dp(10), dp(4))\n            minHeight = 0\n            minimumHeight = dp(32)\n            setOnClickListener {\n                displayedMonth = YearMonth.now()\n                loadMonth(forceNetwork = false, fromSwipe = false)\n            }\n        }\n        actionRow.addView(btnToday, LayoutParams(LayoutParams.WRAP_CONTENT, dp(32)))\n\n        btnRefresh = Button(context).apply {\n            isAllCaps = false\n            setTextColor(Color.parseColor("#38BDF8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n            setPadding(dp(10), dp(4), dp(10), dp(4))\n            minHeight = 0\n            minimumHeight = dp(32)\n            setOnClickListener { loadMonth(forceNetwork = true, fromSwipe = false) }\n        }\n        actionRow.addView(\n            btnRefresh,\n            LayoutParams(LayoutParams.WRAP_CONTENT, dp(32)).apply {\n                marginStart = dp(6)\n            }\n        )\n\n        btnShare = Button(context).apply {\n            isAllCaps = false\n            setTextColor(Color.parseColor("#E2E8F0"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n            setPadding(dp(10), dp(4), dp(10), dp(4))\n            minHeight = 0\n            minimumHeight = dp(32)\n            setOnClickListener { openShareMenu() }\n        }\n        actionRow.addView(\n            btnShare,\n            LayoutParams(LayoutParams.WRAP_CONTENT, dp(32)).apply {\n                marginStart = dp(6)\n            }\n        )\n\n        val spacer = View(context)\n        actionRow.addView(spacer, LayoutParams(0, 1, 1f))\n\n        progressBar = ProgressBar(context, null, android.R.attr.progressBarStyleSmall).apply {\n            isIndeterminate = true\n            visibility = View.GONE\n        }\n        actionRow.addView(progressBar, LayoutParams(dp(18), dp(18)))\n\n        txtStatus = TextView(context).apply {\n            setTextColor(Color.parseColor("#94A3B8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 11f)\n            setPadding(dp(5), 0, 0, 0)\n        }\n        actionRow.addView(txtStatus, LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT))\n\n        headerCard.addView(actionRow, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n        addView(\n            headerCard,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                bottomMargin = dp(8)\n            }\n        )\n\n        swipeRefresh = SwipeRefreshLayout(context).apply {\n            setOnRefreshListener { loadMonth(forceNetwork = true, fromSwipe = true) }\n        }\n\n        val scroll = ScrollView(context).apply {\n            isFillViewport = true\n        }\n        val scrollBody = LinearLayout(context).apply {\n            orientation = VERTICAL\n        }\n        gridContainer = LinearLayout(context).apply {\n            orientation = VERTICAL\n        }\n        scrollBody.addView(gridContainer, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        txtMonthSummary = TextView(context).apply {\n            setTextColor(Color.parseColor("#CBD5E1"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f)\n            gravity = Gravity.CENTER\n            setPadding(dp(10), dp(9), dp(10), dp(9))\n            visibility = View.GONE\n        }\n        scrollBody.addView(\n            txtMonthSummary,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                topMargin = dp(8)\n                bottomMargin = dp(6)\n            }\n        )\n\n        scroll.addView(scrollBody, FrameLayout.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n        swipeRefresh.addView(scroll)\n        addView(swipeRefresh, LayoutParams(LayoutParams.MATCH_PARENT, 0, 1f))\n\n        applyThemeColors()\n    }\n\n    fun applyThemeColors() {\n        val bg = UiStyleHelper.bgHex(context)\n        val card = UiStyleHelper.cardHex(context)\n        val cardAlt = UiStyleHelper.cardAltHex(context)\n        val headerBtn = UiStyleHelper.headerCellHex(context)\n        val border = UiStyleHelper.borderHex(context)\n        val borderStrong = UiStyleHelper.borderStrongHex(context)\n\n        setBackgroundColor(Color.parseColor(bg))\n        UiStyleHelper.configureSwipeRefresh(swipeRefresh)\n        headerCard.background = UiStyleHelper.roundedBg(context, card, border, 12f)\n        btnPrev.background = UiStyleHelper.rippleRoundedBg(context, headerBtn, borderStrong, 10f)\n        btnNext.background = UiStyleHelper.rippleRoundedBg(context, headerBtn, borderStrong, 10f)\n        txtMonthTitle.background = UiStyleHelper.rippleRoundedBg(context, cardAlt, border, 10f)\n        btnToday.background = UiStyleHelper.rippleRoundedBg(context, headerBtn, borderStrong, 8f)\n        btnRefresh.background = UiStyleHelper.rippleRoundedBg(context, headerBtn, borderStrong, 8f)\n        btnShare.background = UiStyleHelper.rippleRoundedBg(context, headerBtn, borderStrong, 8f)\n        txtMonthSummary.background = UiStyleHelper.roundedBg(context, card, border, 10f)\n    }\n\n    private fun animateMonthSlide(direction: Int) {\n        gridContainer.animate().cancel()\n        val shift = dp(24).toFloat() * direction\n        gridContainer.translationX = shift\n        gridContainer.alpha = 0.35f\n        gridContainer.animate()\n            .translationX(0f)\n            .alpha(1f)\n            .setDuration(150L)\n            .start()\n    }\n\n    override fun dispatchTouchEvent(ev: MotionEvent): Boolean {\n        when (ev.actionMasked) {\n            MotionEvent.ACTION_DOWN -> {\n                swipeDownX = ev.x\n                swipeDownY = ev.y\n            }\n            MotionEvent.ACTION_UP -> {\n                val dx = ev.x - swipeDownX\n                val dy = ev.y - swipeDownY\n                if (abs(dx) > dp(64) && abs(dx) > abs(dy) * 1.8f) {\n                    val cancelEv = MotionEvent.obtain(ev)\n                    cancelEv.action = MotionEvent.ACTION_CANCEL\n                    super.dispatchTouchEvent(cancelEv)\n                    cancelEv.recycle()\n\n                    val dir = if (dx < 0f) 1 else -1\n                    displayedMonth = if (dir > 0) displayedMonth.plusMonths(1) else displayedMonth.minusMonths(1)\n                    animateMonthSlide(dir)\n                    loadMonth(forceNetwork = false, fromSwipe = false)\n                    return true\n                }\n            }\n        }\n        return super.dispatchTouchEvent(ev)\n    }\n\n    fun onShow(forceNetwork: Boolean = false) {\n        applyThemeColors()\n        updateLocalizedLabels()\n        loadMonth(forceNetwork = forceNetwork, fromSwipe = false)\n    }\n\n    fun refreshFromCacheAndNetwork() {\n        applyThemeColors()\n        updateLocalizedLabels()\n        loadMonth(forceNetwork = true, fromSwipe = false)\n    }\n\n    private fun updateLocalizedLabels() {\n        val en = DemoModeHelper.isEnglish(context)\n        val monthName = (if (en) enMonths else fiMonths)[displayedMonth.monthValue - 1]\n        txtMonthTitle.text = "$monthName ${displayedMonth.year} ▾"\n        btnToday.text = if (en) "Today" else "Tänään"\n        btnRefresh.text = if (en) "↻" else "↻"\n        btnShare.text = if (en) "↗ Share" else "↗ Jaa"\n    }\n\n    private fun buildCombinedDayMap(): Map<LocalDate, CalendarDisplayDay> {\n        val combined = LinkedHashMap<LocalDate, CalendarDisplayDay>(adjacentDayMap.size + (currentData?.days?.size ?: 0))\n        combined.putAll(adjacentDayMap)\n        currentData?.days?.let { combined.putAll(it) }\n        return combined\n    }\n\n    private fun loadAdjacentMonthsCacheSync(ym: YearMonth): Pair<Map<LocalDate, CalendarDisplayDay>, Set<String>> {\n        val map = LinkedHashMap<LocalDate, CalendarDisplayDay>()\n        val loadedKeys = LinkedHashSet<String>()\n        val prevYm = ym.minusMonths(1)\n        val nextYm = ym.plusMonths(1)\n        if (DemoModeHelper.isDemoEnabled(context)) {\n            val demoShifts = DemoModeHelper.generateDemoWorkShifts(context)\n            NumeronApiClient.buildMonthDisplayFromCachedShifts(demoShifts, prevYm.year, prevYm.monthValue)?.days?.let { map.putAll(it) }\n            NumeronApiClient.buildMonthDisplayFromCachedShifts(demoShifts, nextYm.year, nextYm.monthValue)?.days?.let { map.putAll(it) }\n            return map to loadedKeys\n        }\n        val cachedShifts = CalendarSyncHelper.loadCachedShifts(context)\n        for (adjYm in listOf(prevYm, nextYm)) {\n            val mem = memoryMonths[adjYm]?.first\n            val disk = mem ?: NumeronApiClient.loadMonthDisplayCache(context, adjYm.year, adjYm.monthValue)\n            if (disk != null) {\n                loadedKeys.add(adjYm.toString())\n                map.putAll(disk.days)\n            } else {\n                cachedShifts?.let {\n                    NumeronApiClient.buildMonthDisplayFromCachedShifts(it, adjYm.year, adjYm.monthValue)\n                }?.days?.let { map.putAll(it) }\n            }\n        }\n        return map to loadedKeys\n    }\n\n    private fun buildRenderKey(): String {\n        val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n        val en = DemoModeHelper.isEnglish(context)\n        val isDemo = DemoModeHelper.isDemoEnabled(context)\n        val amoled = UiStyleHelper.isAmoled(context)\n        val morningRgb = prefs.getInt("color_morning_rgb", SettingsDialogHelper.DEFAULT_MORNING_RGB)\n        val eveningRgb = prefs.getInt("color_evening_rgb", SettingsDialogHelper.DEFAULT_EVENING_RGB)\n        val nightRgb = prefs.getInt("color_night_rgb", SettingsDialogHelper.DEFAULT_NIGHT_RGB)\n        val showPeriods = prefs.getBoolean("show_shift_periods", true)\n        val showHolidays = prefs.getBoolean("show_finnish_holidays", true)\n        val showShortRest = prefs.getBoolean("show_short_rest_warning", true)\n        val balanceEnabled = PeriodBalanceManager.isEnabled(context)\n        val balVer = PeriodBalanceManager.version\n        val anchor = prefs.getString("shift_period_anchor_iso", "2026-12-28").orEmpty()\n        return "$displayedMonth|$en|$isDemo|$amoled|$morningRgb|$eveningRgb|$nightRgb|$showPeriods|$showHolidays|$showShortRest|$balanceEnabled|$balVer|$currentMonthLoaded|${adjacentLoadedMonths.size}|$anchor|${LocalDate.now()}"\n    }\n\n    private fun renderCalendarGridIfChanged(forceRender: Boolean = false) {\n        val key = buildRenderKey()\n        val data = currentData\n        val adjSize = adjacentDayMap.size\n        if (!forceRender && key == lastRenderedRenderKey && data == lastRenderedData && adjSize == lastRenderedAdjacentSize) {\n            return\n        }\n        lastRenderedRenderKey = key\n        lastRenderedData = data\n        lastRenderedAdjacentSize = adjSize\n        renderCalendarGrid()\n    }\n\n    private fun storeMemoryMonth(ym: YearMonth, data: MonthDisplayData, fetchedAtMs: Long) {\n        memoryMonths.remove(ym)\n        memoryMonths[ym] = data to fetchedAtMs\n        if (memoryMonths.size > 12) {\n            val oldest = memoryMonths.keys.firstOrNull()\n            if (oldest != null) memoryMonths.remove(oldest)\n        }\n    }\n\n    private fun scheduleNextMonthPrefetch(baseYm: YearMonth) {\n        if (DemoModeHelper.isDemoEnabled(context)) return\n        val baseUrl = UrlNormalizer.getSavedBaseUrl(context)\n        if (baseUrl.isBlank()) return\n        val nextYm = baseYm.plusMonths(1)\n        val nowMs = System.currentTimeMillis()\n        val existingMem = memoryMonths[nextYm]\n        if (existingMem != null && (nowMs - existingMem.second) < 5L * 60_000L) return\n\n        prefetchJob?.cancel()\n        prefetchJob = scope.launch {\n            val diskAgeOk = withContext(Dispatchers.IO) {\n                val savedMs = NumeronApiClient.getMonthCacheSavedAtMs(context, nextYm.year, nextYm.monthValue)\n                if (savedMs > 0L && (System.currentTimeMillis() - savedMs) < 10L * 60_000L) {\n                    val diskData = NumeronApiClient.loadMonthDisplayCache(context, nextYm.year, nextYm.monthValue)\n                    diskData to savedMs\n                } else {\n                    null\n                }\n            }\n            if (diskAgeOk != null && diskAgeOk.first != null) {\n                storeMemoryMonth(nextYm, diskAgeOk.first!!, diskAgeOk.second)\n                if (displayedMonth == baseYm) {\n                    val adjPair = withContext(Dispatchers.IO) { loadAdjacentMonthsCacheSync(baseYm) }\n                    adjacentDayMap = adjPair.first\n                    adjacentLoadedMonths = adjPair.second\n                    renderCalendarGridIfChanged()\n                }\n                return@launch\n            }\n\n            val html = NumeronApiClient.fetchMonthCalendarHtml(context, nextYm.year, nextYm.monthValue)\n                ?: return@launch\n            val parsed = withContext(Dispatchers.Default) {\n                NumeronParser.parseMonthForDisplay(html)\n            } ?: return@launch\n            withContext(Dispatchers.IO) {\n                NumeronApiClient.saveMonthDisplayCache(context, parsed)\n                PeriodBalanceManager.recordMonthSnapshot(context, parsed)\n            }\n            storeMemoryMonth(nextYm, parsed, System.currentTimeMillis())\n            if (displayedMonth == baseYm) {\n                val adjPair = withContext(Dispatchers.IO) { loadAdjacentMonthsCacheSync(baseYm) }\n                adjacentDayMap = adjPair.first\n                adjacentLoadedMonths = adjPair.second\n                renderCalendarGridIfChanged()\n            }\n        }\n    }\n\n    private fun loadMonth(forceNetwork: Boolean, fromSwipe: Boolean = false) {\n        val ym = displayedMonth\n        val en = DemoModeHelper.isEnglish(context)\n        updateLocalizedLabels()\n        loadJob?.cancel()\n\n        val epoch = SessionCookieStore.sessionEpoch\n        if (epoch != lastSessionEpoch) {\n            lastSessionEpoch = epoch\n            memoryMonths.clear()\n            adjacentDayMap = emptyMap()\n            adjacentLoadedMonths = emptySet()\n            currentMonthLoaded = false\n            lastRenderedRenderKey = null\n            lastRenderedData = null\n        }\n\n        if (DemoModeHelper.isDemoEnabled(context)) {\n            swipeRefresh.isRefreshing = false\n            progressBar.visibility = View.GONE\n            txtStatus.text = "Demo"\n            val demoShifts = DemoModeHelper.generateDemoWorkShifts(context)\n            currentData = NumeronApiClient.buildMonthDisplayFromCachedShifts(demoShifts, ym.year, ym.monthValue)\n                ?: MonthDisplayData(ym.year, ym.monthValue, emptyMap())\n            val adjPair = loadAdjacentMonthsCacheSync(ym)\n            adjacentDayMap = adjPair.first\n            adjacentLoadedMonths = adjPair.second\n            currentMonthLoaded = false\n            renderCalendarGridIfChanged()\n            return\n        }\n\n        val baseUrl = UrlNormalizer.getSavedBaseUrl(context)\n        if (baseUrl.isBlank()) {\n            swipeRefresh.isRefreshing = false\n            progressBar.visibility = View.GONE\n            txtStatus.text = if (en) "Set organization in Settings" else "Aseta organisaatio asetuksista"\n            currentData = MonthDisplayData(ym.year, ym.monthValue, emptyMap())\n            adjacentDayMap = emptyMap()\n            adjacentLoadedMonths = emptySet()\n            currentMonthLoaded = false\n            renderCalendarGridIfChanged()\n            return\n        }\n\n        // 1. Muistivälimuisti + 2 min tuoreusaika\n        val memEntry = memoryMonths[ym]\n        if (memEntry != null) {\n            currentData = memEntry.first\n            currentMonthLoaded = true\n            if (!forceNetwork && (System.currentTimeMillis() - memEntry.second) < 120_000L) {\n                swipeRefresh.isRefreshing = false\n                progressBar.visibility = View.GONE\n                txtStatus.text = UiStyleHelper.formatUpdatedLabel(context, memEntry.second, isCache = false)\n                loadJob = scope.launch {\n                    val adjPair = withContext(Dispatchers.IO) { loadAdjacentMonthsCacheSync(ym) }\n                    if (ym == displayedMonth) {\n                        adjacentDayMap = adjPair.first\n                        adjacentLoadedMonths = adjPair.second\n                        renderCalendarGridIfChanged()\n                        scheduleNextMonthPrefetch(ym)\n                    }\n                }\n                return\n            }\n            renderCalendarGridIfChanged()\n        }\n\n        loadJob = scope.launch {\n            var cachedMonth: MonthDisplayData? = memEntry?.first\n            var cachedAtMs: Long = memEntry?.second ?: 0L\n            var hasAnyCache = (cachedMonth != null)\n\n            val diskLoad = withContext(Dispatchers.IO) {\n                val adjPair = loadAdjacentMonthsCacheSync(ym)\n                if (cachedMonth == null) {\n                    val mCache = NumeronApiClient.loadMonthDisplayCache(context, ym.year, ym.monthValue)\n                    val mSaved = NumeronApiClient.getMonthCacheSavedAtMs(context, ym.year, ym.monthValue)\n                    val fallback = if (mCache == null) {\n                        CalendarSyncHelper.loadCachedShifts(context)?.let {\n                            NumeronApiClient.buildMonthDisplayFromCachedShifts(it, ym.year, ym.monthValue)\n                        }\n                    } else {\n                        null\n                    }\n                    arrayOf<Any?>(mCache ?: fallback, mSaved, adjPair, mCache != null)\n                } else {\n                    arrayOf<Any?>(cachedMonth, cachedAtMs, adjPair, true)\n                }\n            }\n            if (ym != displayedMonth) return@launch\n\n            @Suppress("UNCHECKED_CAST")\n            val adjPair = diskLoad[2] as Pair<Map<LocalDate, CalendarDisplayDay>, Set<String>>\n            adjacentDayMap = adjPair.first\n            adjacentLoadedMonths = adjPair.second\n            currentMonthLoaded = (diskLoad[3] as? Boolean) == true\n            if (cachedMonth == null) {\n                cachedMonth = diskLoad[0] as? MonthDisplayData\n                cachedAtMs = (diskLoad[1] as? Long) ?: 0L\n                hasAnyCache = (cachedMonth != null)\n                currentData = cachedMonth ?: MonthDisplayData(ym.year, ym.monthValue, emptyMap())\n            }\n            renderCalendarGridIfChanged()\n\n            if (!fromSwipe) {\n                progressBar.visibility = View.VISIBLE\n            }\n            txtStatus.text = if (!forceNetwork && hasAnyCache) {\n                if (en) "Updating…" else "Päivitetään…"\n            } else {\n                if (en) "Loading…" else "Ladataan…"\n            }\n\n            val html = NumeronApiClient.fetchMonthCalendarHtml(context, ym.year, ym.monthValue)\n            if (ym != displayedMonth) return@launch\n\n            swipeRefresh.isRefreshing = false\n            progressBar.visibility = View.GONE\n            if (html != null) {\n                val parsed = withContext(Dispatchers.Default) {\n                    NumeronParser.parseMonthForDisplay(html)\n                }\n                if (parsed != null) {\n                    val fetchedAt = System.currentTimeMillis()\n                    withContext(Dispatchers.IO) {\n                        NumeronApiClient.saveMonthDisplayCache(context, parsed)\n                        PeriodBalanceManager.recordMonthSnapshot(context, parsed)\n                    }\n                    storeMemoryMonth(ym, parsed, fetchedAt)\n                    currentData = parsed\n                    currentMonthLoaded = true\n                    txtStatus.text = UiStyleHelper.formatUpdatedLabel(context, fetchedAt, isCache = false)\n                    renderCalendarGridIfChanged()\n                    scheduleNextMonthPrefetch(ym)\n                    return@launch\n                }\n            }\n\n            txtStatus.text = if (hasAnyCache) {\n                UiStyleHelper.formatUpdatedLabel(context, cachedAtMs, isCache = true)\n                    .ifEmpty { if (en) "Offline cache" else "Välimuisti" }\n            } else {\n                if (en) "Could not load" else "Lataus epäonnistui"\n            }\n        }\n    }\n\n    private fun resolvePeriodAnchorMonday(): LocalDate {\n        val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n        val raw = prefs.getString("shift_period_anchor_iso", "2026-12-28").orEmpty().trim()\n        val parsed = try {\n            LocalDate.parse(raw)\n        } catch (_: Exception) {\n            LocalDate.of(2026, 12, 28)\n        }\n        return parsed.with(DayOfWeek.MONDAY)\n    }\n\n    private data class PeriodStats(\n        val shiftCount: Int,\n        val totalMinutes: Int,\n        val morningCount: Int,\n        val eveningCount: Int,\n        val nightCount: Int\n    )\n\n    private fun computePeriodStats(\n        periodStart: LocalDate,\n        periodEnd: LocalDate,\n        combinedMap: Map<LocalDate, CalendarDisplayDay>\n    ): PeriodStats {\n        var count = 0\n        var mins = 0\n        var morning = 0\n        var evening = 0\n        var night = 0\n        var d = periodStart\n        while (!d.isAfter(periodEnd)) {\n            val day = combinedMap[d]\n            if (day != null) {\n                for (shift in day.shifts) {\n                    count++\n                    val dur = if (shift.endMinutes >= shift.startMinutes) {\n                        shift.endMinutes - shift.startMinutes\n                    } else {\n                        (24 * 60 - shift.startMinutes) + shift.endMinutes\n                    }\n                    mins += dur\n                    val crossesMidnight = shift.endMinutes < shift.startMinutes\n                    when {\n                        crossesMidnight || shift.startMinutes >= 20 * 60 || shift.startMinutes < 4 * 60 -> night++\n                        shift.startMinutes >= 11 * 60 + 30 -> evening++\n                        else -> morning++\n                    }\n                }\n            }\n            d = d.plusDays(1)\n        }\n        return PeriodStats(count, mins, morning, evening, night)\n    }\n\n    private fun computeShortRestMinutes(\n        date: LocalDate,\n        combinedMap: Map<LocalDate, CalendarDisplayDay>\n    ): Long? {\n        val todayShifts = combinedMap[date]?.shifts.orEmpty()\n        if (todayShifts.isEmpty()) return null\n\n        val firstToday = todayShifts.minByOrNull { it.startMinutes } ?: return null\n        val firstStartDt = LocalDateTime.of(\n            date,\n            LocalTime.of((firstToday.startMinutes / 60).coerceIn(0, 23), (firstToday.startMinutes % 60).coerceIn(0, 59))\n        )\n\n        var latestPrevEnd: LocalDateTime? = null\n        val prevDate = date.minusDays(1)\n        combinedMap[prevDate]?.shifts?.forEach { prevShift ->\n            val endDate = if (prevShift.endMinutes < prevShift.startMinutes) date else prevDate\n            val endDt = LocalDateTime.of(\n                endDate,\n                LocalTime.of((prevShift.endMinutes / 60).coerceIn(0, 23), (prevShift.endMinutes % 60).coerceIn(0, 59))\n            )\n            if (!endDt.isAfter(firstStartDt) && (latestPrevEnd == null || endDt.isAfter(latestPrevEnd))) {\n                latestPrevEnd = endDt\n            }\n        }\n\n        val prevEnd = latestPrevEnd ?: return null\n        val restMins = Duration.between(prevEnd, firstStartDt).toMinutes()\n        return if (restMins in 1L..659L) restMins else null\n    }\n\n    private fun openShareMenu() {\n        val en = DemoModeHelper.isEnglish(context)\n        val ym = displayedMonth\n        val monthName = (if (en) enMonths else fiMonths)[ym.monthValue - 1]\n        val monthTitle = "$monthName ${ym.year}"\n        val anchorMonday = resolvePeriodAnchorMonday()\n        val refDate = if (YearMonth.now() == ym) LocalDate.now() else ym.atDay(1)\n        val refMonday = refDate.with(DayOfWeek.MONDAY)\n        val periodIdx = Math.floorDiv(ChronoUnit.DAYS.between(anchorMonday, refMonday), 21L)\n        val periodStart = anchorMonday.plusDays(periodIdx * 21L)\n        val periodEnd = periodStart.plusDays(20L)\n\n        ScheduleShareHelper.showShareDialog(\n            context = context,\n            ym = ym,\n            monthTitle = monthTitle,\n            allDayMap = buildCombinedDayMap(),\n            periodStart = periodStart,\n            periodEnd = periodEnd\n        )\n    }\n\n    private fun showPeriodSummaryDialog(\n        periodStart: LocalDate,\n        periodEnd: LocalDate,\n        stats: PeriodStats,\n        periodBalance: PeriodBalanceResult?,\n        combinedMap: Map<LocalDate, CalendarDisplayDay>\n    ) {\n        val en = DemoModeHelper.isEnglish(context)\n        val cardBg = UiStyleHelper.cardHex(context)\n        val altBg = UiStyleHelper.cardAltHex(context)\n        val btnBg = UiStyleHelper.headerCellHex(context)\n        val border = UiStyleHelper.borderHex(context)\n        val borderStrong = UiStyleHelper.borderStrongHex(context)\n        val fmt = DateTimeFormatter.ofPattern("d.M.yyyy")\n\n        val root = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setBackgroundColor(Color.parseColor(cardBg))\n            setPadding(dp(18), dp(16), dp(18), dp(14))\n        }\n\n        root.addView(\n            TextView(context).apply {\n                text = if (en) "3-WEEK SHIFT PERIOD" else "3 VIIKON TYÖVUOROLISTA"\n                setTextColor(Color.parseColor("#38BDF8"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 11.5f)\n                setTypeface(null, Typeface.BOLD)\n            }\n        )\n        root.addView(\n            TextView(context).apply {\n                text = "${periodStart.format(fmt)} – ${periodEnd.format(fmt)}"\n                setTextColor(Color.parseColor("#F1F5F9"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 17f)\n                setTypeface(null, Typeface.BOLD)\n                setPadding(0, dp(3), 0, dp(10))\n            }\n        )\n\n        val summaryBox = LinearLayout(context).apply {\n            orientation = VERTICAL\n            background = UiStyleHelper.roundedBg(context, altBg, border, 10f)\n            setPadding(dp(12), dp(10), dp(12), dp(10))\n        }\n\n        if (stats.shiftCount > 0) {\n            val hoursStr = ScheduleShareHelper.formatHours(stats.totalMinutes, en)\n            val word = if (en) {\n                if (stats.shiftCount == 1) "shift" else "shifts"\n            } else {\n                if (stats.shiftCount == 1) "vuoro" else "vuoroa"\n            }\n            summaryBox.addView(\n                TextView(context).apply {\n                    text = "${stats.shiftCount} $word  •  $hoursStr h"\n                    setTextColor(Color.WHITE)\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 18f)\n                    setTypeface(null, Typeface.BOLD)\n                }\n            )\n            val parts = mutableListOf<String>()\n            if (stats.morningCount > 0) parts.add(if (en) "${stats.morningCount} morn" else "${stats.morningCount} aamu")\n            if (stats.eveningCount > 0) parts.add(if (en) "${stats.eveningCount} eve" else "${stats.eveningCount} ilta")\n            if (stats.nightCount > 0) parts.add(if (en) "${stats.nightCount} night" else "${stats.nightCount} yö")\n            if (parts.isNotEmpty()) {\n                summaryBox.addView(\n                    TextView(context).apply {\n                        text = parts.joinToString(" / ")\n                        setTextColor(Color.parseColor("#CBD5E1"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n                        setPadding(0, dp(4), 0, 0)\n                    }\n                )\n            }\n        } else {\n            summaryBox.addView(\n                TextView(context).apply {\n                    text = if (en) "No shifts loaded for this period yet" else "Ei ladattuja vuoroja tälle jaksolle"\n                    setTextColor(Color.parseColor("#94A3B8"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n                }\n            )\n        }\n        root.addView(\n            summaryBox,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                bottomMargin = dp(10)\n            }\n        )\n\n        val dialog = AlertDialog.Builder(context)\n            .setView(root)\n            .create()\n\n        // Saldoseuranta-osio (näytetään kun ominaisuus on päällä asetuksissa eikä olla demotilassa)\n        if (PeriodBalanceManager.isEnabled(context) && !DemoModeHelper.isDemoEnabled(context)) {\n            val balBox = LinearLayout(context).apply {\n                orientation = VERTICAL\n                background = UiStyleHelper.roundedBg(context, altBg, border, 10f)\n                setPadding(dp(12), dp(10), dp(12), dp(10))\n            }\n\n            if (periodBalance != null) {\n                val planH = PeriodBalanceManager.formatHoursDecimal(periodBalance.plannedMinutes, en)\n                val effH = PeriodBalanceManager.formatHoursDecimal(periodBalance.effectiveMinutes, en)\n                val diffExact = PeriodBalanceManager.formatSignedExact(periodBalance.diffMinutes, en)\n                val diffColor = when {\n                    periodBalance.diffMinutes > 0 -> "#4ADE80"\n                    periodBalance.diffMinutes < 0 -> "#F87171"\n                    else -> "#CBD5E1"\n                }\n\n                balBox.addView(\n                    TextView(context).apply {\n                        text = if (en) "Period balance: $diffExact" else "Jakson saldo: $diffExact"\n                        setTextColor(Color.parseColor(diffColor))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 15.5f)\n                        setTypeface(null, Typeface.BOLD)\n                    }\n                )\n                val sickNote = if (periodBalance.creditedSickDays > 0) {\n                    val sickH = PeriodBalanceManager.formatHoursDecimal(periodBalance.creditedSickMinutes, en)\n                    if (en) " (incl. ${periodBalance.creditedSickDays} sick leave credited: $sickH h)"\n                    else " (sis. ${periodBalance.creditedSickDays} hyvitetty SL: $sickH h)"\n                } else {\n                    ""\n                }\n                balBox.addView(\n                    TextView(context).apply {\n                        text = if (en) {\n                            "Published plan: $planH h  •  Credited total: $effH h$sickNote"\n                        } else {\n                            "Julkaistu lista: $planH h  •  Hyväksiluettu: $effH h$sickNote"\n                        }\n                        setTextColor(Color.parseColor("#CBD5E1"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f)\n                        setPadding(0, dp(4), 0, 0)\n                    }\n                )\n\n                val balActions = LinearLayout(context).apply {\n                    orientation = HORIZONTAL\n                    setPadding(0, dp(8), 0, 0)\n                }\n                val btnResetBase = Button(context).apply {\n                    text = if (en) "Set current as plan" else "Aseta nykyinen pohjaksi"\n                    isAllCaps = false\n                    setTextColor(Color.parseColor("#38BDF8"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 11.5f)\n                    background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 7f)\n                    setPadding(dp(8), dp(4), dp(8), dp(4))\n                    minHeight = 0\n                    minimumHeight = dp(32)\n                    setOnClickListener {\n                        if (PeriodBalanceManager.saveManualBaseline(context, periodStart, periodEnd, combinedMap)) {\n                            dialog.dismiss()\n                            renderCalendarGridIfChanged(forceRender = true)\n                            Toast.makeText(\n                                context,\n                                if (en) "Period baseline updated" else "Jakson pohjasuunnitelma päivitetty",\n                                Toast.LENGTH_SHORT\n                            ).show()\n                        }\n                    }\n                }\n                val btnClearBase = Button(context).apply {\n                    text = if (en) "Clear" else "Poista pohja"\n                    isAllCaps = false\n                    setTextColor(Color.parseColor("#FCA5A5"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 11.5f)\n                    background = UiStyleHelper.rippleRoundedBg(context, "#3F1D24", "#DC2626", 7f)\n                    setPadding(dp(8), dp(4), dp(8), dp(4))\n                    minHeight = 0\n                    minimumHeight = dp(32)\n                    setOnClickListener {\n                        PeriodBalanceManager.removeBaseline(context, periodStart)\n                        dialog.dismiss()\n                        renderCalendarGridIfChanged(forceRender = true)\n                        Toast.makeText(\n                            context,\n                            if (en) "Period balance cleared" else "Jakson saldoseuranta poistettu",\n                            Toast.LENGTH_SHORT\n                        ).show()\n                    }\n                }\n                balActions.addView(btnResetBase, LayoutParams(0, dp(32), 1.3f).apply { marginEnd = dp(6) })\n                balActions.addView(btnClearBase, LayoutParams(0, dp(32), 1f))\n                balBox.addView(balActions, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n            } else {\n                val isFuture = periodStart.isAfter(LocalDate.now())\n                balBox.addView(\n                    TextView(context).apply {\n                        text = if (isFuture) {\n                            if (en) "Baseline will be saved automatically once all shifts of this period are loaded."\n                            else "Pohjasuunnitelma tallentuu automaattisesti, kun listan vuorot on ladattu."\n                        } else {\n                            if (en) "Automatic balance tracking starts from the next not-yet-started shift period."\n                            else "Automaattinen saldoseuranta alkaa seuraavasta vielä alkamattomasta listasta."\n                        }\n                        setTextColor(Color.parseColor("#94A3B8"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n                    }\n                )\n                if (stats.shiftCount > 0) {\n                    val btnStartNow = Button(context).apply {\n                        text = if (en) "Track this period from current shifts" else "Aseta nykyinen lista pohjaksi"\n                        isAllCaps = false\n                        setTextColor(Color.parseColor("#38BDF8"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n                        setTypeface(null, Typeface.BOLD)\n                        background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 8f)\n                        setPadding(dp(10), dp(6), dp(10), dp(6))\n                        minHeight = 0\n                        minimumHeight = dp(34)\n                        setOnClickListener {\n                            if (PeriodBalanceManager.saveManualBaseline(context, periodStart, periodEnd, combinedMap)) {\n                                dialog.dismiss()\n                                renderCalendarGridIfChanged(forceRender = true)\n                                Toast.makeText(\n                                    context,\n                                    if (en) "Baseline saved for this period" else "Pohjasuunnitelma tallennettu tälle jaksolle",\n                                    Toast.LENGTH_SHORT\n                                ).show()\n                            }\n                        }\n                    }\n                    balBox.addView(\n                        btnStartNow,\n                        LayoutParams(LayoutParams.MATCH_PARENT, dp(34)).apply {\n                            topMargin = dp(8)\n                        }\n                    )\n                }\n            }\n\n            root.addView(\n                balBox,\n                LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                    bottomMargin = dp(12)\n                }\n            )\n        }\n\n        val shareRow = LinearLayout(context).apply {\n            orientation = HORIZONTAL\n        }\n        val btnShareImg = Button(context).apply {\n            text = if (en) "🖼 Share PNG" else "🖼 Jaa kuvana"\n            isAllCaps = false\n            setTextColor(Color.WHITE)\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n            setTypeface(null, Typeface.BOLD)\n            background = UiStyleHelper.rippleRoundedBg(context, "#1982C4", "#38BDF8", 8f, "#44FFFFFF")\n            setOnClickListener {\n                dialog.dismiss()\n                ScheduleShareHelper.sharePeriodDirectly(context, periodStart, periodEnd, combinedMap, asImage = true)\n            }\n        }\n        val btnShareTxt = Button(context).apply {\n            text = if (en) "📝 Share text" else "📝 Jaa tekstinä"\n            isAllCaps = false\n            setTextColor(Color.parseColor("#E2E8F0"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n            background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 8f)\n            setOnClickListener {\n                dialog.dismiss()\n                ScheduleShareHelper.sharePeriodDirectly(context, periodStart, periodEnd, combinedMap, asImage = false)\n            }\n        }\n        shareRow.addView(btnShareImg, LayoutParams(0, dp(40), 1f).apply { marginEnd = dp(8) })\n        shareRow.addView(btnShareTxt, LayoutParams(0, dp(40), 1f))\n        root.addView(shareRow)\n\n        val btnClose = Button(context).apply {\n            text = if (en) "Close" else "Sulje"\n            isAllCaps = false\n            setTextColor(Color.parseColor("#CBD5E1"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n            background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 8f)\n            setOnClickListener { dialog.dismiss() }\n        }\n        root.addView(\n            btnClose,\n            LayoutParams(LayoutParams.MATCH_PARENT, dp(38)).apply {\n                topMargin = dp(8)\n            }\n        )\n\n        dialog.window?.setBackgroundDrawable(UiStyleHelper.roundedBg(context, cardBg, "#38BDF8", 14f))\n        dialog.show()\n    }\n\n    private fun renderCalendarGrid() {\n        gridContainer.removeAllViews()\n        val en = DemoModeHelper.isEnglish(context)\n        val ym = displayedMonth\n        val today = LocalDate.now()\n        val dayMap = currentData?.days.orEmpty()\n        val combinedMap = buildCombinedDayMap()\n\n        val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n        val morningRgb = prefs.getInt("color_morning_rgb", SettingsDialogHelper.DEFAULT_MORNING_RGB)\n        val eveningRgb = prefs.getInt("color_evening_rgb", SettingsDialogHelper.DEFAULT_EVENING_RGB)\n        val nightRgb = prefs.getInt("color_night_rgb", SettingsDialogHelper.DEFAULT_NIGHT_RGB)\n        val showShiftPeriods = prefs.getBoolean("show_shift_periods", true)\n        val showHolidays = prefs.getBoolean("show_finnish_holidays", true)\n        val showShortRest = prefs.getBoolean("show_short_rest_warning", true)\n        val periodDays = 21L\n        val anchorMonday = resolvePeriodAnchorMonday()\n        val shortDateFmt = DateTimeFormatter.ofPattern("d.M.")\n\n        val borderHex = UiStyleHelper.borderHex(context)\n        val headerBgHex = UiStyleHelper.headerCellHex(context)\n        val weekendHeaderBgHex = UiStyleHelper.weekendHeaderHex(context)\n        val weekColBgHex = UiStyleHelper.weekColHex(context)\n\n        // Otsikkorivi: Vko + Ma..Su\n        val headerRow = LinearLayout(context).apply {\n            orientation = HORIZONTAL\n        }\n        val dayHeaders = if (en) {\n            arrayOf("Wk", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")\n        } else {\n            arrayOf("Vko", "Ma", "Ti", "Ke", "To", "Pe", "La", "Su")\n        }\n        for (i in dayHeaders.indices) {\n            val isWeekendHeader = (i == 6 || i == 7)\n            val tv = TextView(context).apply {\n                text = dayHeaders[i]\n                gravity = Gravity.CENTER\n                setTextColor(Color.parseColor(if (isWeekendHeader) "#93C5FD" else "#CBD5E1"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, if (i == 0) 10f else 11.5f)\n                setTypeface(null, Typeface.BOLD)\n                background = UiStyleHelper.cellBg(context, if (isWeekendHeader) weekendHeaderBgHex else headerBgHex, borderHex)\n                setPadding(dp(1), dp(6), dp(1), dp(6))\n            }\n            val lp = if (i == 0) LayoutParams(dp(26), LayoutParams.WRAP_CONTENT) else LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f)\n            headerRow.addView(tv, lp)\n        }\n        gridContainer.addView(headerRow, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n        val firstOfMonth = ym.atDay(1)\n        val lastOfMonth = ym.atEndOfMonth()\n        val startMonday = firstOfMonth.with(DayOfWeek.MONDAY)\n        val endSunday = lastOfMonth.with(DayOfWeek.SUNDAY)\n\n        var weekStart = startMonday\n        val weekFields = WeekFields.ISO\n\n        val availableMonths = LinkedHashSet<String>().apply {\n            if (currentMonthLoaded) add(ym.toString())\n            addAll(adjacentLoadedMonths)\n        }\n        val balanceEnabled = PeriodBalanceManager.isEnabled(context) && !DemoModeHelper.isDemoEnabled(context)\n        val periodBalanceCache = HashMap<LocalDate, PeriodBalanceResult?>()\n\n        // Kuukausikoosteen laskurit\n        var shiftCount = 0\n        var totalMinutes = 0\n        var morningCount = 0\n        var eveningCount = 0\n        var nightCount = 0\n        var monthBalanceDiff = 0\n        var monthHasTrackedBalance = false\n\n        while (!weekStart.isAfter(endSunday)) {\n            val daysFromAnchor = ChronoUnit.DAYS.between(anchorMonday, weekStart)\n            val periodIdx = Math.floorDiv(daysFromAnchor, periodDays)\n            val periodStart = anchorMonday.plusDays(periodIdx * periodDays)\n            val periodEnd = periodStart.plusDays(periodDays - 1L)\n            val isPeriodStartRow = (weekStart == periodStart)\n            val periodAccentHex = if (abs(periodIdx) % 2L == 0L) "#38BDF8" else "#F59E0B"\n\n            val periodBalance = if (balanceEnabled) {\n                periodBalanceCache.getOrPut(periodStart) {\n                    PeriodBalanceManager.computePeriodBalance(\n                        context = context,\n                        periodStart = periodStart,\n                        periodEnd = periodEnd,\n                        combinedDayMap = combinedMap,\n                        availableMonths = availableMonths\n                    )\n                }\n            } else {\n                null\n            }\n\n            // 3 viikon työvuorolistajakson raja: vuorot • tunnit • aamu/ilta/yö (+ saldorivi jos pohja tallennettu)\n            if (showShiftPeriods && (isPeriodStartRow || weekStart == startMonday)) {\n                val pStats = computePeriodStats(periodStart, periodEnd, combinedMap)\n                val periodBar = LinearLayout(context).apply {\n                    orientation = VERTICAL\n                    background = UiStyleHelper.cellBg(\n                        context = context,\n                        fillHex = if (isPeriodStartRow) UiStyleHelper.periodBarStartHex(context) else UiStyleHelper.periodBarMidHex(context),\n                        strokeHex = borderHex,\n                        leftAccentHex = periodAccentHex\n                    )\n                    setPadding(dp(8), dp(4), dp(8), dp(4))\n                    setOnClickListener {\n                        showPeriodSummaryDialog(periodStart, periodEnd, pStats, periodBalance, combinedMap)\n                    }\n                }\n\n                val topLine = LinearLayout(context).apply {\n                    orientation = HORIZONTAL\n                    gravity = Gravity.CENTER_VERTICAL\n                }\n                val labelPrefix = if (en) "Period" else "Työvuorolista"\n                val rangeText = "${periodStart.format(shortDateFmt)}–${periodEnd.format(shortDateFmt)}"\n                val pTv = TextView(context).apply {\n                    text = "$labelPrefix $rangeText"\n                    setTextColor(Color.parseColor(if (isPeriodStartRow) periodAccentHex else "#94A3B8"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 10.5f)\n                    setTypeface(null, if (isPeriodStartRow) Typeface.BOLD else Typeface.NORMAL)\n                }\n                topLine.addView(pTv, LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT))\n\n                if (pStats.shiftCount > 0) {\n                    val pHours = ScheduleShareHelper.formatHours(pStats.totalMinutes, en)\n                    val unitShort = if (en) "sh" else "v"\n                    val pBreakdownParts = mutableListOf<String>()\n                    if (pStats.morningCount > 0) pBreakdownParts.add(if (en) "${pStats.morningCount} morn" else "${pStats.morningCount} aamu")\n                    if (pStats.eveningCount > 0) pBreakdownParts.add(if (en) "${pStats.eveningCount} eve" else "${pStats.eveningCount} ilta")\n                    if (pStats.nightCount > 0) pBreakdownParts.add(if (en) "${pStats.nightCount} night" else "${pStats.nightCount} yö")\n                    val pBreakdownSuffix = if (pBreakdownParts.isNotEmpty()) " • ${pBreakdownParts.joinToString(" / ")}" else ""\n\n                    val hTv = TextView(context).apply {\n                        text = "${pStats.shiftCount} $unitShort • $pHours h$pBreakdownSuffix"\n                        gravity = Gravity.END\n                        setTextColor(Color.parseColor(if (isPeriodStartRow) "#E2E8F0" else "#94A3B8"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 10f)\n                        setTypeface(null, Typeface.BOLD)\n                    }\n                    topLine.addView(\n                        hTv,\n                        LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f).apply {\n                            marginStart = dp(6)\n                        }\n                    )\n                }\n                periodBar.addView(topLine, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n                if (periodBalance != null) {\n                    val balRow = LinearLayout(context).apply {\n                        orientation = HORIZONTAL\n                        gravity = Gravity.CENTER_VERTICAL\n                        setPadding(0, dp(2), 0, 0)\n                    }\n                    val planH = PeriodBalanceManager.formatHoursDecimal(periodBalance.plannedMinutes, en)\n                    val sickTag = if (periodBalance.creditedSickDays > 0) {\n                        if (en) " • ${periodBalance.creditedSickDays} SL credited" else " • ${periodBalance.creditedSickDays} SL hyvitetty"\n                    } else {\n                        ""\n                    }\n                    val origTv = TextView(context).apply {\n                        text = (if (en) "Plan $planH h" else "Alkup. $planH h") + sickTag\n                        setTextColor(Color.parseColor("#94A3B8"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 9.5f)\n                    }\n                    balRow.addView(origTv, LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f))\n\n                    val signedStr = PeriodBalanceManager.formatSignedHours(periodBalance.diffMinutes, en)\n                    val balColorHex = when {\n                        periodBalance.diffMinutes > 0 -> "#4ADE80"\n                        periodBalance.diffMinutes < 0 -> "#F87171"\n                        else -> "#94A3B8"\n                    }\n                    val balTv = TextView(context).apply {\n                        text = if (en) "Bal $signedStr" else "Saldo $signedStr"\n                        setTextColor(Color.parseColor(balColorHex))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 10f)\n                        setTypeface(null, Typeface.BOLD)\n                    }\n                    balRow.addView(balTv, LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT))\n                    periodBar.addView(balRow, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n                }\n\n                gridContainer.addView(periodBar, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n            }\n\n            val row = LinearLayout(context).apply {\n                orientation = HORIZONTAL\n                minimumHeight = dp(72)\n            }\n\n            // Viikkonumero + jakson vasen värikorostusreuna\n            val weekNum = weekStart.get(weekFields.weekOfWeekBasedYear())\n            val wkTv = TextView(context).apply {\n                text = weekNum.toString()\n                gravity = Gravity.TOP or Gravity.CENTER_HORIZONTAL\n                setTextColor(Color.parseColor("#64748B"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 10f)\n                background = UiStyleHelper.cellBg(\n                    context = context,\n                    fillHex = weekColBgHex,\n                    strokeHex = borderHex,\n                    leftAccentHex = if (showShiftPeriods) periodAccentHex else null\n                )\n                setPadding(dp(3), dp(5), dp(1), dp(4))\n            }\n            row.addView(wkTv, LayoutParams(dp(26), LayoutParams.MATCH_PARENT))\n\n            for (offset in 0..6) {\n                val date = weekStart.plusDays(offset.toLong())\n                val isCurrentMonth = (date.monthValue == ym.monthValue && date.year == ym.year)\n                val isToday = (date == today)\n                val isPast = date.isBefore(today)\n                val isWeekend = (offset == 5 || offset == 6)\n                val holidayName = if (showHolidays && isCurrentMonth) FinnishHolidays.getHolidayName(date, en) else null\n                val dayData = dayMap[date]\n                val dayBalance = if (isCurrentMonth) periodBalance?.dayDetails?.get(date) else null\n                if (isCurrentMonth && periodBalance != null) {\n                    monthHasTrackedBalance = true\n                    if (dayBalance != null) {\n                        monthBalanceDiff += dayBalance.diffMinutes\n                    }\n                }\n                val shortRestMins = if (showShortRest && isCurrentMonth) computeShortRestMinutes(date, combinedMap) else null\n\n                if (isCurrentMonth && dayData != null) {\n                    for (shift in dayData.shifts) {\n                        shiftCount++\n                        val dur = if (shift.endMinutes >= shift.startMinutes) {\n                            shift.endMinutes - shift.startMinutes\n                        } else {\n                            (24 * 60 - shift.startMinutes) + shift.endMinutes\n                        }\n                        totalMinutes += dur\n                        val crossesMidnight = shift.endMinutes < shift.startMinutes\n                        when {\n                            crossesMidnight || shift.startMinutes >= 20 * 60 || shift.startMinutes < 4 * 60 -> nightCount++\n                            shift.startMinutes >= 11 * 60 + 30 -> eveningCount++\n                            else -> morningCount++\n                        }\n                    }\n                }\n\n                val cellBgColor = when {\n                    isToday -> UiStyleHelper.todayCellHex(context)\n                    !isCurrentMonth -> UiStyleHelper.otherMonthCellHex(context)\n                    holidayName != null -> UiStyleHelper.holidayCellHex(context)\n                    isPast -> if (isWeekend) UiStyleHelper.pastWeekendCellHex(context) else UiStyleHelper.pastCellHex(context)\n                    isWeekend -> UiStyleHelper.weekendCellHex(context)\n                    else -> UiStyleHelper.cardHex(context)\n                }\n                val cellBorderColor = if (isToday) "#38BDF8" else borderHex\n\n                val cell = LinearLayout(context).apply {\n                    orientation = VERTICAL\n                    background = if (isCurrentMonth) {\n                        UiStyleHelper.rippleCellBg(context, cellBgColor, cellBorderColor)\n                    } else {\n                        UiStyleHelper.cellBg(context, cellBgColor, cellBorderColor)\n                    }\n                    setPadding(dp(2), dp(2), dp(2), dp(3))\n                    minimumHeight = dp(72)\n                    if (isCurrentMonth) {\n                        setOnClickListener { showDayDetailsDialog(date, dayData, holidayName, shortRestMins, dayBalance) }\n                    }\n                }\n\n                // Päivänumero + lyhyt lepoaika -merkki + kommenttipallukka\n                val topRow = LinearLayout(context).apply {\n                    orientation = HORIZONTAL\n                    gravity = Gravity.CENTER_VERTICAL\n                }\n                val numTv = TextView(context).apply {\n                    text = date.dayOfMonth.toString()\n                    setTextColor(\n                        when {\n                            !isCurrentMonth -> Color.parseColor("#64748B")\n                            isToday -> Color.parseColor("#38BDF8")\n                            holidayName != null -> Color.parseColor("#F87171")\n                            isWeekend -> Color.parseColor("#93C5FD")\n                            else -> Color.parseColor("#F1F5F9")\n                        }\n                    )\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 11.5f)\n                    setTypeface(null, Typeface.BOLD)\n                    setPadding(dp(2), 0, 0, dp(1))\n                }\n                topRow.addView(numTv, LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f))\n\n                if (shortRestMins != null) {\n                    val warnTv = TextView(context).apply {\n                        text = "⚠"\n                        setTextColor(Color.parseColor("#FBBF24"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 9.5f)\n                        setPadding(0, 0, dp(2), 0)\n                    }\n                    topRow.addView(warnTv, LayoutParams(LayoutParams.WRAP_CONTENT, LayoutParams.WRAP_CONTENT))\n                }\n\n                if (dayData?.hasCommentCircle == true) {\n                    val dot = View(context).apply {\n                        background = GradientDrawable().apply {\n                            shape = GradientDrawable.OVAL\n                            setColor(Color.parseColor("#F59E0B"))\n                        }\n                    }\n                    topRow.addView(\n                        dot,\n                        LayoutParams(dp(6), dp(6)).apply {\n                            marginEnd = dp(2)\n                        }\n                    )\n                }\n                cell.addView(topRow, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n\n                // Suomen arkipyhän nimi pienenä merkintänä\n                if (holidayName != null) {\n                    val holTv = TextView(context).apply {\n                        text = holidayName\n                        setTextColor(Color.parseColor("#FCA5A5"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 8.5f)\n                        setTypeface(null, Typeface.BOLD)\n                        maxLines = 1\n                        ellipsize = TextUtils.TruncateAt.END\n                        setPadding(dp(2), 0, dp(1), dp(1))\n                    }\n                    cell.addView(holTv, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n                }\n\n                // Poissaolot (yhtenäiset lomapalkit peräkkäisille päiville)\n                val prevDate = date.minusDays(1)\n                val nextDate = date.plusDays(1)\n                val prevAbsences = if (offset > 0) dayMap[prevDate]?.absences.orEmpty() else emptyList()\n                val nextAbsences = if (offset < 6) dayMap[nextDate]?.absences.orEmpty() else emptyList()\n\n                dayData?.absences?.forEach { absItem ->\n                    if (absItem.kind == "sick" &&\n                        dayBalance?.isCreditedSick == true &&\n                        dayBalance.plannedStartText.isNotEmpty() &&\n                        dayData.shifts.isEmpty()\n                    ) {\n                        val sickBox = LinearLayout(context).apply {\n                            orientation = VERTICAL\n                            gravity = Gravity.CENTER\n                            background = UiStyleHelper.roundedBg(context, "#991B1B", "#F87171", 4f)\n                            setPadding(dp(2), dp(2), dp(2), dp(2))\n                        }\n                        sickBox.addView(\n                            TextView(context).apply {\n                                text = "${dayBalance.plannedStartText}\\n${dayBalance.plannedEndText}"\n                                setTextColor(Color.WHITE)\n                                setTextSize(TypedValue.COMPLEX_UNIT_SP, 9.5f)\n                                setTypeface(null, Typeface.BOLD)\n                                gravity = Gravity.CENTER\n                                maxLines = 2\n                            },\n                            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT)\n                        )\n                        sickBox.addView(\n                            TextView(context).apply {\n                                text = if (en) "SL cred." else "SL hyv."\n                                setTextColor(Color.parseColor("#FECACA"))\n                                setTextSize(TypedValue.COMPLEX_UNIT_SP, 8f)\n                                setTypeface(null, Typeface.BOLD)\n                                gravity = Gravity.CENTER\n                                maxLines = 1\n                            },\n                            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT)\n                        )\n                        cell.addView(\n                            sickBox,\n                            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                                bottomMargin = dp(2)\n                            }\n                        )\n                    } else {\n                        val connectedLeft = prevAbsences.any { it.title.equals(absItem.title, ignoreCase = true) }\n                        val connectedRight = nextAbsences.any { it.title.equals(absItem.title, ignoreCase = true) }\n                        val (bgHex, fgHex) = when (absItem.kind) {\n                            "vacation" -> "#15803D" to "#FFFFFF"\n                            "sick" -> "#B91C1C" to "#FFFFFF"\n                            else -> "#334155" to "#F1F5F9"\n                        }\n                        val r = dp(4).toFloat()\n                        val rL = if (connectedLeft) 0f else r\n                        val rR = if (connectedRight) 0f else r\n                        val badge = TextView(context).apply {\n                            text = if (connectedLeft) " " else absItem.title\n                            setTextColor(Color.parseColor(fgHex))\n                            setTextSize(TypedValue.COMPLEX_UNIT_SP, 9.5f)\n                            setTypeface(null, Typeface.BOLD)\n                            maxLines = 1\n                            ellipsize = TextUtils.TruncateAt.END\n                            background = GradientDrawable().apply {\n                                shape = GradientDrawable.RECTANGLE\n                                setColor(Color.parseColor(bgHex))\n                                cornerRadii = floatArrayOf(rL, rL, rR, rR, rR, rR, rL, rL)\n                            }\n                            setPadding(if (connectedLeft) 0 else dp(3), dp(1), if (connectedRight) 0 else dp(3), dp(1))\n                        }\n                        cell.addView(\n                            badge,\n                            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                                bottomMargin = dp(2)\n                            }\n                        )\n                    }\n                }\n\n                // Työvuorot asetusten värikoodeilla\n                dayData?.shifts?.forEach { shift ->\n                    val bgRgb = pickShiftRgb(shift, morningRgb, eveningRgb, nightRgb)\n                    val fgColor = contrastColor(bgRgb)\n                    val label = "${shift.startText}\\n${shift.endText}"\n                    val badge = TextView(context).apply {\n                        text = label\n                        setTextColor(fgColor)\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 10f)\n                        setTypeface(null, Typeface.BOLD)\n                        gravity = Gravity.CENTER\n                        maxLines = 2\n                        background = GradientDrawable().apply {\n                            shape = GradientDrawable.RECTANGLE\n                            cornerRadius = dp(4).toFloat()\n                            setColor(bgRgb)\n                        }\n                        setPadding(dp(2), dp(2), dp(2), dp(2))\n                    }\n                    cell.addView(\n                        badge,\n                        LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                            bottomMargin = dp(2)\n                        }\n                    )\n                }\n\n                // Toiveet\n                dayData?.requests?.forEach { req ->\n                    val badge = TextView(context).apply {\n                        text = req.title\n                        setTextColor(Color.parseColor("#EDE9FE"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 9.5f)\n                        setTypeface(null, Typeface.BOLD)\n                        maxLines = 1\n                        ellipsize = TextUtils.TruncateAt.END\n                        background = UiStyleHelper.roundedBg(context, "#2E1F47", "#8B5CF6", 4f)\n                        setPadding(dp(3), dp(1), dp(3), dp(1))\n                    }\n                    cell.addView(\n                        badge,\n                        LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                            bottomMargin = dp(2)\n                        }\n                    )\n                }\n\n                row.addView(cell, LayoutParams(0, LayoutParams.MATCH_PARENT, 1f))\n            }\n\n            gridContainer.addView(row, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n            weekStart = weekStart.plusWeeks(1)\n        }\n\n        // Kuukauden pikakooste\n        if (shiftCount > 0) {\n            val hoursStr = ScheduleShareHelper.formatHours(totalMinutes, en)\n            val breakdownParts = mutableListOf<String>()\n            if (morningCount > 0) breakdownParts.add(if (en) "$morningCount morn" else "$morningCount aamu")\n            if (eveningCount > 0) breakdownParts.add(if (en) "$eveningCount eve" else "$eveningCount ilta")\n            if (nightCount > 0) breakdownParts.add(if (en) "$nightCount night" else "$nightCount yö")\n\n            val shiftWord = if (en) {\n                if (shiftCount == 1) "shift" else "shifts"\n            } else {\n                if (shiftCount == 1) "vuoro" else "vuoroa"\n            }\n            val breakdownSuffix = if (breakdownParts.isNotEmpty()) "  •  ${breakdownParts.joinToString(" / ")}" else ""\n            val baseText = "$shiftCount $shiftWord • $hoursStr h$breakdownSuffix"\n            if (balanceEnabled && monthHasTrackedBalance) {\n                val sb = SpannableStringBuilder(baseText)\n                sb.append("  •  ")\n                val balStart = sb.length\n                val signedStr = PeriodBalanceManager.formatSignedHours(monthBalanceDiff, en)\n                val balWord = if (en) "bal" else "saldo"\n                sb.append("$balWord $signedStr")\n                val balColor = when {\n                    monthBalanceDiff > 0 -> Color.parseColor("#4ADE80")\n                    monthBalanceDiff < 0 -> Color.parseColor("#F87171")\n                    else -> Color.parseColor("#94A3B8")\n                }\n                sb.setSpan(ForegroundColorSpan(balColor), balStart, sb.length, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\n                sb.setSpan(StyleSpan(Typeface.BOLD), balStart, sb.length, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\n                txtMonthSummary.text = sb\n            } else {\n                txtMonthSummary.text = baseText\n            }\n            txtMonthSummary.visibility = View.VISIBLE\n        } else {\n            txtMonthSummary.visibility = View.GONE\n        }\n    }\n\n    private fun launchShiftAlarm(shift: CalendarDisplayShift) {\n        val en = DemoModeHelper.isEnglish(context)\n        val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n        val leadMins = prefs.getInt("alarm_lead_minutes", 75).coerceIn(5, 240)\n        val alarmTotal = ((shift.startMinutes - leadMins) % (24 * 60) + (24 * 60)) % (24 * 60)\n        val hour = alarmTotal / 60\n        val minute = alarmTotal % 60\n        val locPart = shift.location.takeIf { it.isNotBlank() }?.let { " ($it)" }.orEmpty()\n        val msg = if (en) {\n            "Work shift ${shift.startText}$locPart"\n        } else {\n            "Työvuoro klo ${shift.startText}$locPart"\n        }\n\n        val intent = Intent(AlarmClock.ACTION_SET_ALARM).apply {\n            putExtra(AlarmClock.EXTRA_HOUR, hour)\n            putExtra(AlarmClock.EXTRA_MINUTES, minute)\n            putExtra(AlarmClock.EXTRA_MESSAGE, msg)\n            putExtra(AlarmClock.EXTRA_SKIP_UI, false)\n        }\n        try {\n            context.startActivity(intent)\n        } catch (_: Exception) {\n            Toast.makeText(\n                context,\n                if (en) "Clock app not found" else "Kellosovellusta ei löytynyt",\n                Toast.LENGTH_SHORT\n            ).show()\n        }\n    }\n\n    private fun showDayDetailsDialog(\n        date: LocalDate,\n        dayData: CalendarDisplayDay?,\n        holidayName: String?,\n        shortRestMins: Long?,\n        dayBalance: DayBalanceInfo?\n    ) {\n        val en = DemoModeHelper.isEnglish(context)\n        val fiWeekdays = arrayOf("Ma", "Ti", "Ke", "To", "Pe", "La", "Su")\n        val enWeekdays = arrayOf("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")\n        val dowStr = (if (en) enWeekdays else fiWeekdays)[date.dayOfWeek.value - 1]\n        val dateStr = date.format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))\n\n        val cardBg = UiStyleHelper.cardHex(context)\n        val altBg = UiStyleHelper.cardAltHex(context)\n        val btnBg = UiStyleHelper.headerCellHex(context)\n        val border = UiStyleHelper.borderHex(context)\n        val borderStrong = UiStyleHelper.borderStrongHex(context)\n\n        val root = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setBackgroundColor(Color.parseColor(cardBg))\n            setPadding(dp(18), dp(16), dp(18), dp(14))\n        }\n\n        val titleTv = TextView(context).apply {\n            text = "$dowStr $dateStr"\n            setTextColor(Color.parseColor("#F1F5F9"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 18f)\n            setTypeface(null, Typeface.BOLD)\n        }\n        root.addView(titleTv)\n\n        val contentBox = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setPadding(0, dp(10), 0, dp(10))\n        }\n\n        if (holidayName != null) {\n            contentBox.addView(\n                TextView(context).apply {\n                    text = "🇫🇮 $holidayName"\n                    setTextColor(Color.parseColor("#FCA5A5"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n                    setTypeface(null, Typeface.BOLD)\n                    background = UiStyleHelper.roundedBg(context, "#3F1D24", "#EF4444", 8f)\n                    setPadding(dp(10), dp(7), dp(10), dp(7))\n                },\n                LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                    bottomMargin = dp(8)\n                }\n            )\n        }\n\n        if (shortRestMins != null) {\n            val h = shortRestMins / 60L\n            val m = shortRestMins % 60L\n            val durStr = if (en) {\n                if (m > 0L) "${h}h ${m}m" else "${h}h"\n            } else {\n                if (m > 0L) "$h h $m min" else "$h h"\n            }\n            contentBox.addView(\n                TextView(context).apply {\n                    text = if (en) {\n                        "⚠ Short rest: $durStr since previous shift"\n                    } else {\n                        "⚠ Lyhyt lepoaika: $durStr edellisestä vuorosta"\n                    }\n                    setTextColor(Color.parseColor("#FEF3C7"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n                    setTypeface(null, Typeface.BOLD)\n                    background = UiStyleHelper.roundedBg(context, "#3B2810", "#F59E0B", 8f)\n                    setPadding(dp(10), dp(7), dp(10), dp(7))\n                },\n                LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                    bottomMargin = dp(8)\n                }\n            )\n        }\n\n        if (dayBalance != null) {\n            if (dayBalance.isCreditedSick) {\n                val credMin = (dayBalance.plannedMinutes - dayBalance.actualMinutes).coerceAtLeast(0)\n                val credH = PeriodBalanceManager.formatHoursDecimal(credMin, en)\n                val timesPart = if (dayBalance.plannedStartText.isNotEmpty()) {\n                    " ${dayBalance.plannedStartText}–${dayBalance.plannedEndText}"\n                } else {\n                    ""\n                }\n                contentBox.addView(\n                    TextView(context).apply {\n                        text = if (en) {\n                            "Credited sick leave:$timesPart ($credH h) — no negative balance"\n                        } else {\n                            "Hyvitetty sairausloma:$timesPart ($credH h) — ei kerrytä miinussaldoa"\n                        }\n                        setTextColor(Color.parseColor("#FECACA"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f)\n                        setTypeface(null, Typeface.BOLD)\n                        background = UiStyleHelper.roundedBg(context, "#3F1D24", "#EF4444", 8f)\n                        setPadding(dp(10), dp(7), dp(10), dp(7))\n                    },\n                    LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                        bottomMargin = dp(8)\n                    }\n                )\n            } else if (dayBalance.diffMinutes != 0) {\n                val diffStr = PeriodBalanceManager.formatSignedExact(dayBalance.diffMinutes, en)\n                val planInfo = if (dayBalance.plannedMinutes > 0 && dayBalance.plannedStartText.isNotEmpty()) {\n                    if (en) " (plan ${dayBalance.plannedStartText}–${dayBalance.plannedEndText})"\n                    else " (alkup. ${dayBalance.plannedStartText}–${dayBalance.plannedEndText})"\n                } else if (dayBalance.plannedMinutes == 0) {\n                    if (en) " (added shift)" else " (lisävuoro)"\n                } else {\n                    ""\n                }\n                val isPos = dayBalance.diffMinutes > 0\n                contentBox.addView(\n                    TextView(context).apply {\n                        text = (if (en) "Balance impact: " else "Saldovaikutus: ") + diffStr + planInfo\n                        setTextColor(Color.parseColor(if (isPos) "#4ADE80" else "#FCA5A5"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f)\n                        setTypeface(null, Typeface.BOLD)\n                        background = UiStyleHelper.roundedBg(\n                            context,\n                            if (isPos) "#0F2E26" else "#3F1D24",\n                            if (isPos) "#22C55E" else "#F87171",\n                            8f\n                        )\n                        setPadding(dp(10), dp(7), dp(10), dp(7))\n                    },\n                    LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                        bottomMargin = dp(8)\n                    }\n                )\n            }\n        }\n\n        var hasAny = false\n        dayData?.shifts?.forEach { shift ->\n            hasAny = true\n            val card = LinearLayout(context).apply {\n                orientation = VERTICAL\n                background = UiStyleHelper.roundedBg(context, altBg, border, 10f)\n                setPadding(dp(12), dp(10), dp(12), dp(10))\n            }\n            card.addView(\n                TextView(context).apply {\n                    text = "${shift.startText} – ${shift.endText}"\n                    setTextColor(Color.parseColor("#38BDF8"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 16f)\n                    setTypeface(null, Typeface.BOLD)\n                }\n            )\n            if (shift.location.isNotEmpty()) {\n                card.addView(\n                    TextView(context).apply {\n                        text = shift.location\n                        setTextColor(Color.parseColor("#F1F5F9"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 14f)\n                        setTypeface(null, Typeface.BOLD)\n                        setPadding(0, dp(2), 0, 0)\n                    }\n                )\n            }\n            val sub = listOf(shift.shiftName, shift.role).filter { it.isNotBlank() }.joinToString(" • ")\n            if (sub.isNotEmpty()) {\n                card.addView(\n                    TextView(context).apply {\n                        text = sub\n                        setTextColor(Color.parseColor("#CBD5E1"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n                        setPadding(0, dp(2), 0, 0)\n                    }\n                )\n            }\n            contentBox.addView(\n                card,\n                LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                    bottomMargin = dp(8)\n                }\n            )\n        }\n\n        dayData?.absences?.forEach { absItem ->\n            hasAny = true\n            val borderHex = when (absItem.kind) {\n                "vacation" -> "#22C55E"\n                "sick" -> "#F87171"\n                else -> "#64748B"\n            }\n            val tv = TextView(context).apply {\n                text = absItem.title\n                setTextColor(Color.parseColor("#F1F5F9"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 14f)\n                setTypeface(null, Typeface.BOLD)\n                background = UiStyleHelper.roundedBg(context, altBg, borderHex, 8f)\n                setPadding(dp(12), dp(9), dp(12), dp(9))\n            }\n            contentBox.addView(\n                tv,\n                LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                    bottomMargin = dp(8)\n                }\n            )\n        }\n\n        dayData?.requests?.forEach { req ->\n            hasAny = true\n            val tv = TextView(context).apply {\n                text = (if (en) "Request: " else "Toive: ") + req.title\n                setTextColor(Color.parseColor("#EDE9FE"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n                background = UiStyleHelper.roundedBg(context, "#2E1F47", "#8B5CF6", 8f)\n                setPadding(dp(12), dp(9), dp(12), dp(9))\n            }\n            contentBox.addView(\n                tv,\n                LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                    bottomMargin = dp(8)\n                }\n            )\n        }\n\n        if (!hasAny) {\n            contentBox.addView(\n                TextView(context).apply {\n                    text = if (en) "No scheduled shifts" else "Ei merkittyjä vuoroja"\n                    setTextColor(Color.parseColor("#94A3B8"))\n                    setTextSize(TypedValue.COMPLEX_UNIT_SP, 14f)\n                }\n            )\n        }\n\n        val commentTv = TextView(context).apply {\n            setTextColor(Color.parseColor("#FDE68A"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n            background = UiStyleHelper.roundedBg(context, "#2A2210", "#F59E0B", 8f)\n            setPadding(dp(10), dp(8), dp(10), dp(8))\n            visibility = if (dayData?.hasCommentCircle == true && !DemoModeHelper.isDemoEnabled(context)) View.VISIBLE else View.GONE\n            text = if (en) "Loading shift comment..." else "Haetaan vuorokommenttia..."\n        }\n        contentBox.addView(\n            commentTv,\n            LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT).apply {\n                bottomMargin = dp(8)\n            }\n        )\n\n        root.addView(contentBox)\n\n        val dialog = AlertDialog.Builder(context)\n            .setView(root)\n            .create()\n\n        // Aseta herätys yhdellä napautuksella\n        val earliestShift = dayData?.shifts?.minByOrNull { it.startMinutes }\n        if (earliestShift != null) {\n            val prefs = context.getSharedPreferences("NumeronPrefs", Context.MODE_PRIVATE)\n            val leadMins = prefs.getInt("alarm_lead_minutes", 75).coerceIn(5, 240)\n            val alarmTotal = ((earliestShift.startMinutes - leadMins) % (24 * 60) + (24 * 60)) % (24 * 60)\n            val alarmTimeStr = String.format("%02d:%02d", alarmTotal / 60, alarmTotal % 60)\n\n            val btnAlarm = Button(context).apply {\n                text = if (en) "⏰ Set alarm ($alarmTimeStr)" else "⏰ Aseta herätys (klo $alarmTimeStr)"\n                isAllCaps = false\n                setTextColor(Color.parseColor("#E0F2FE"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n                setTypeface(null, Typeface.BOLD)\n                background = UiStyleHelper.rippleRoundedBg(context, "#1E3A5F", "#0284C7", 8f)\n                setOnClickListener {\n                    dialog.dismiss()\n                    launchShiftAlarm(earliestShift)\n                }\n            }\n            root.addView(\n                btnAlarm,\n                LayoutParams(LayoutParams.MATCH_PARENT, dp(40)).apply {\n                    bottomMargin = dp(8)\n                }\n            )\n        }\n\n        if (!DemoModeHelper.isDemoEnabled(context)) {\n            val baseUrl = UrlNormalizer.getSavedBaseUrl(context)\n            val btnRow = LinearLayout(context).apply {\n                orientation = HORIZONTAL\n            }\n            val isoDate = date.toString()\n            val listDateParam = URLEncoder.encode("${date.monthValue}/${date.dayOfMonth}/${date.year} 00:00:00", "UTF-8")\n\n            val btnAddReq = Button(context).apply {\n                text = if (en) "+ Add Request" else "+ Lisää toive"\n                isAllCaps = false\n                setTextColor(Color.WHITE)\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n                setTypeface(null, Typeface.BOLD)\n                background = UiStyleHelper.rippleRoundedBg(context, "#1982C4", "#38BDF8", 8f, "#44FFFFFF")\n                setOnClickListener {\n                    dialog.dismiss()\n                    if (baseUrl.isNotBlank()) {\n                        onOpenWebUrl(\n                            "$baseUrl/PersonRequests/Edit?calendarView=Month&returnValue=$isoDate",\n                            if (en) "New request ($dateStr)" else "Uusi toive ($dateStr)"\n                        )\n                    }\n                }\n            }\n            btnRow.addView(\n                btnAddReq,\n                LayoutParams(0, dp(40), 1f).apply {\n                    marginEnd = dp(8)\n                }\n            )\n\n            val btnOpenDay = Button(context).apply {\n                text = if (en) "Open day" else "Avaa päivä"\n                isAllCaps = false\n                setTextColor(Color.parseColor("#E2E8F0"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)\n                background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 8f)\n                setOnClickListener {\n                    dialog.dismiss()\n                    if (baseUrl.isNotBlank()) {\n                        onOpenWebUrl(\n                            "$baseUrl/Calendar/List?date=$listDateParam",\n                            dateStr\n                        )\n                    }\n                }\n            }\n            btnRow.addView(btnOpenDay, LayoutParams(0, dp(40), 1f))\n            root.addView(btnRow)\n\n            if (dayData?.hasCommentCircle == true && baseUrl.isNotBlank()) {\n                scope.launch {\n                    val comment = withContext(Dispatchers.IO) {\n                        val cookies = SessionCookieStore.getCookieHeader(context, baseUrl)\n                        NumeronParser.fetchDayComments(baseUrl, cookies, date)\n                    }\n                    if (dialog.isShowing) {\n                        if (!comment.isNullOrBlank()) {\n                            commentTv.text = (if (en) "Note: " else "Huomio: ") + comment\n                            commentTv.visibility = View.VISIBLE\n                        } else {\n                            commentTv.visibility = View.GONE\n                        }\n                    }\n                }\n            }\n        }\n\n        val btnClose = Button(context).apply {\n            text = if (en) "Close" else "Sulje"\n            isAllCaps = false\n            setTextColor(Color.parseColor("#CBD5E1"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n            background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 8f)\n            setOnClickListener { dialog.dismiss() }\n        }\n        root.addView(\n            btnClose,\n            LayoutParams(LayoutParams.MATCH_PARENT, dp(38)).apply {\n                topMargin = dp(8)\n            }\n        )\n\n        dialog.window?.setBackgroundDrawable(UiStyleHelper.roundedBg(context, cardBg, "#38BDF8", 14f))\n        dialog.show()\n    }\n\n    private fun showMonthJumpDialog() {\n        val en = DemoModeHelper.isEnglish(context)\n        val shortNames = if (en) enShortMonths else fiShortMonths\n        var selectedYear = displayedMonth.year\n        val realNow = YearMonth.now()\n        val cardBg = UiStyleHelper.cardHex(context)\n        val altBg = UiStyleHelper.cardAltHex(context)\n        val btnBg = UiStyleHelper.headerCellHex(context)\n        val border = UiStyleHelper.borderHex(context)\n        val borderStrong = UiStyleHelper.borderStrongHex(context)\n\n        val root = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setBackgroundColor(Color.parseColor(cardBg))\n            setPadding(dp(16), dp(16), dp(16), dp(14))\n        }\n\n        root.addView(\n            TextView(context).apply {\n                text = if (en) "JUMP TO MONTH & YEAR" else "SIIRRY KUUKAUTEEN JA VUOTEEN"\n                setTextColor(Color.parseColor("#38BDF8"))\n                setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)\n                setTypeface(null, Typeface.BOLD)\n                gravity = Gravity.CENTER\n                setPadding(0, 0, 0, dp(10))\n            }\n        )\n\n        val yearRow = LinearLayout(context).apply {\n            orientation = HORIZONTAL\n            gravity = Gravity.CENTER_VERTICAL\n            background = UiStyleHelper.roundedBg(context, altBg, border, 10f)\n            setPadding(dp(8), dp(6), dp(8), dp(6))\n        }\n\n        val yearLabel = TextView(context).apply {\n            text = selectedYear.toString()\n            setTextColor(Color.parseColor("#F1F5F9"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 18f)\n            setTypeface(null, Typeface.BOLD)\n            gravity = Gravity.CENTER\n        }\n\n        val gridHost = LinearLayout(context).apply {\n            orientation = VERTICAL\n            setPadding(0, dp(12), 0, dp(12))\n        }\n\n        val dialog = AlertDialog.Builder(context)\n            .setView(root)\n            .create()\n\n        fun renderMonths() {\n            yearLabel.text = selectedYear.toString()\n            gridHost.removeAllViews()\n            for (r in 0..3) {\n                val mRow = LinearLayout(context).apply {\n                    orientation = HORIZONTAL\n                }\n                for (c in 0..2) {\n                    val mVal = r * 3 + c + 1\n                    val isSelected = (selectedYear == displayedMonth.year && mVal == displayedMonth.monthValue)\n                    val isCurrent = (selectedYear == realNow.year && mVal == realNow.monthValue)\n                    val bgHex = if (isSelected) "#1982C4" else altBg\n                    val borderHex = if (isSelected || isCurrent) "#38BDF8" else border\n                    val btn = Button(context).apply {\n                        text = shortNames[mVal - 1]\n                        isAllCaps = false\n                        setTextColor(if (isSelected) Color.WHITE else Color.parseColor("#E2E8F0"))\n                        setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n                        setTypeface(null, Typeface.BOLD)\n                        background = UiStyleHelper.rippleRoundedBg(context, bgHex, borderHex, 8f)\n                        setOnClickListener {\n                            dialog.dismiss()\n                            displayedMonth = YearMonth.of(selectedYear, mVal)\n                            loadMonth(forceNetwork = false, fromSwipe = false)\n                        }\n                    }\n                    mRow.addView(\n                        btn,\n                        LayoutParams(0, dp(40), 1f).apply {\n                            setMargins(dp(3), dp(3), dp(3), dp(3))\n                        }\n                    )\n                }\n                gridHost.addView(mRow, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))\n            }\n        }\n\n        val btnPrevYear = Button(context).apply {\n            text = "◀"\n            setTextColor(Color.parseColor("#38BDF8"))\n            background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 8f)\n            setOnClickListener {\n                selectedYear -= 1\n                renderMonths()\n            }\n        }\n        val btnNextYear = Button(context).apply {\n            text = "▶"\n            setTextColor(Color.parseColor("#38BDF8"))\n            background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 8f)\n            setOnClickListener {\n                selectedYear += 1\n                renderMonths()\n            }\n        }\n\n        yearRow.addView(btnPrevYear, LayoutParams(dp(42), dp(36)))\n        yearRow.addView(yearLabel, LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f))\n        yearRow.addView(btnNextYear, LayoutParams(dp(42), dp(36)))\n\n        root.addView(yearRow)\n        root.addView(gridHost)\n\n        val footer = LinearLayout(context).apply {\n            orientation = HORIZONTAL\n        }\n        val btnNow = Button(context).apply {\n            text = if (en) "Current month" else "Nykyinen kuukausi"\n            isAllCaps = false\n            setTextColor(Color.parseColor("#38BDF8"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n            background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 8f)\n            setOnClickListener {\n                dialog.dismiss()\n                displayedMonth = YearMonth.now()\n                loadMonth(forceNetwork = false, fromSwipe = false)\n            }\n        }\n        val btnCancel = Button(context).apply {\n            text = if (en) "Cancel" else "Peruuta"\n            isAllCaps = false\n            setTextColor(Color.parseColor("#CBD5E1"))\n            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)\n            background = UiStyleHelper.rippleRoundedBg(context, btnBg, borderStrong, 8f)\n            setOnClickListener { dialog.dismiss() }\n        }\n        footer.addView(btnNow, LayoutParams(0, dp(38), 1f).apply { marginEnd = dp(8) })\n        footer.addView(btnCancel, LayoutParams(0, dp(38), 1f))\n        root.addView(footer)\n\n        renderMonths()\n        dialog.window?.setBackgroundDrawable(UiStyleHelper.roundedBg(context, cardBg, "#38BDF8", 14f))\n        dialog.show()\n    }\n\n    private fun pickShiftRgb(\n        shift: CalendarDisplayShift,\n        morningRgb: Int,\n        eveningRgb: Int,\n        nightRgb: Int\n    ): Int {\n        val crossesMidnight = shift.endMinutes < shift.startMinutes\n        return when {\n            crossesMidnight || shift.startMinutes >= 20 * 60 || shift.startMinutes < 4 * 60 -> nightRgb\n            shift.startMinutes >= 11 * 60 + 30 -> eveningRgb\n            else -> morningRgb\n        }\n    }\n\n    private fun contrastColor(rgb: Int): Int {\n        val lum = 0.299 * Color.red(rgb) + 0.587 * Color.green(rgb) + 0.114 * Color.blue(rgb)\n        return if (lum > 150.0) Color.parseColor("#0F1722") else Color.WHITE\n    }\n\n    private fun dp(value: Int): Int = UiStyleHelper.dp(context, value)\n}\n'


def find_file(filename: str) -> Path | None:
    candidates = [
        Path("app/src/main/java/fi/numeron/vuorovahti") / filename,
        Path("src/main/java/fi/numeron/vuorovahti") / filename,
        Path("app") / filename,
        Path(filename),
    ]
    for c in candidates:
        if c.exists():
            return c
    for p in Path(".").rglob(filename):
        if ".git" not in p.parts and "build" not in p.parts:
            return p
    return None


def read_text_keep_nl(path: Path) -> tuple[str, str]:
    raw = path.read_bytes().decode("utf-8")
    newline = "\r\n" if "\r\n" in raw else "\n"
    return raw.replace("\r\n", "\n"), newline


def write_text_keep_nl(path: Path, content: str, newline: str) -> None:
    normalized = content.replace("\r\n", "\n")
    if newline == "\r\n":
        normalized = normalized.replace("\n", "\r\n")
    path.write_bytes(normalized.encode("utf-8"))


def write_file_exact(path: Path, content: str, label: str) -> bool:
    normalized = content.replace("\r\n", "\n").lstrip("\n")
    if not normalized.endswith("\n"):
        normalized += "\n"
    if path.exists():
        existing, nl = read_text_keep_nl(path)
        if existing == normalized:
            print(f"  [OK - jo ajantasalla] {label} ({path})")
            return False
        write_text_keep_nl(path, normalized, nl)
        print(f"  [PÄIVITETTY] {label} ({path})")
        return True
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(normalized.encode("utf-8"))
    print(f"  [LUOTU] {label} ({path})")
    return True


def replace_once(content: str, old: str, new: str, label: str) -> str:
    if new and new in content:
        print(f"  [OK - jo sovellettu] {label}")
        return content
    if old not in content:
        print(f"  [VAROITUS - kohdetta ei löytynyt] {label}")
        return content
    print(f"  [PÄIVITETTY] {label}")
    return content.replace(old, new, 1)


def patch_settings_dialog_helper(path: Path) -> bool:
    text, nl = read_text_keep_nl(path)
    orig = text

    old_anchor = """        val initialShowHolidays = prefs.getBoolean("show_finnish_holidays", true)"""
    new_anchor = """        val initialPeriodBalance = prefs.getBoolean(PeriodBalanceManager.PREF_ENABLED, true)
        val switchPeriodBalance = createToggleRow(
            parent = calCard,
            title = if (en) "Track 3-week period hour balance" else "Seuraa työvuorolistan tuntisaldoa",
            subtitle = if (en) {
                "Compares worked hours against the published schedule (sick leaves are credited). Automatic tracking starts from the next not-yet-started period."
            } else {
                "Vertaa toteutuneita tunteja julkaistuun listaan (sairauslomat hyvitetään). Laskenta alkaa vasta seuraavasta vielä alkamattomasta listasta."
            },
            initialChecked = initialPeriodBalance
        )

        val initialShowHolidays = prefs.getBoolean("show_finnish_holidays", true)"""

    text = replace_once(
        text,
        old_anchor,
        new_anchor,
        "SettingsDialogHelper: työvuorolistan saldoseurannan kytkin"
    )

    old_save_var = """            val newShowHolidays = switchShowHolidays.isChecked"""
    new_save_var = """            val newPeriodBalance = switchPeriodBalance.isChecked
            val newShowHolidays = switchShowHolidays.isChecked"""
    text = replace_once(
        text,
        old_save_var,
        new_save_var,
        "SettingsDialogHelper: newPeriodBalance luku tallennuksessa"
    )

    old_put = """                .putBoolean("show_finnish_holidays", newShowHolidays)"""
    new_put = """                .putBoolean(PeriodBalanceManager.PREF_ENABLED, newPeriodBalance)
                .putBoolean("show_finnish_holidays", newShowHolidays)"""
    text = replace_once(
        text,
        old_put,
        new_put,
        "SettingsDialogHelper: period_balance_tracking_enabled tallennus"
    )

    if text != orig:
        write_text_keep_nl(path, text, nl)
        return True
    return False


